// Упражнения в тетрадь главы «Выразительные средства». n — постоянный номер: не менять и не переиспользовать.
// Цитаты — из корпуса классики (общественное достояние), дословно, ё восстановлена, стихи — строки через « / »,
// при сокращении — «…». Открытые задания (составить, написать) — с ключом-образцом и признаками, по которым проверяют работу.
// «Задание для абитуриентов» — трудные задания повышенной сложности без названий экзаменов (PRINCIPLES §5.10).
// Скороговорки и пословицы — народные. key — всегда последнее поле.
const VY_CLASSIC=[
// ── Урок 1. Звукопись
 {n:1,l:1,st:1,task:'1) Выписать слова-звукоподражания (слова, которые воспроизводят звуки). 2) Рядом с каждым записать, что или кто издаёт этот звук.',
  obr:'ку-ку — кукушка.',
  body:'ку-ку, окно, тик-так, шуршать, гора, хлоп, дом, жужжать, мяу, облако, бабах, берег, стол, пищать, тропинка, гав',
  key:'Звукоподражания: ку-ку (кукушка), тик-так (часы), шуршать (бумага, листья), хлоп (удар ладонью, дверь), жужжать (пчёлы, мухи), мяу (кошка), бабах (взрыв, падение), пищать (птенцы, мышь), гав (собака). Не звукоподражания: окно, гора, дом, облако, река, стол, тропинка — эти слова называют предметы и звуков не изображают.'},
 {n:2,l:1,st:1,task:'Прочитать вслух скороговорки. 1) Записать, какие звуки повторяются. 2) Назвать приём (повтор согласных — аллитерация, повтор гласных — ассонанс). 3) Объяснить, почему их трудно выговорить.',
  obr:'«Шла Саша по шоссе и сосала сушку»: повторяются [ш] и [с] — аллитерация.',
  body:'1. Шла Саша по шоссе и сосала сушку. 2. Карл у Клары украл кораллы, а Клара у Карла украла кларнет. 3. Тридцать три корабля лавировали, лавировали, да не вылавировали. 4. Ехал Грека через реку, видит Грека — в реке рак. 5. На дворе трава, на траве дрова.',
  key:'1. [ш], [с] — аллитерация. 2. [к], [л], [р] — аллитерация. 3. [т], [р], [л], [в] — аллитерация. 4. [р], [к] — аллитерация. 5. [а], [в], [р] — повторяются гласный [а] и согласные: в скороговорке звуки перемежаются (ассонанс на [а] и аллитерация на [в], [р]). Трудно выговорить: близкие звуки следуют друг за другом, язык «путается». В скороговорках повтор — главная цель, в стихах — средство передать образ.'},
 {n:3,l:1,st:2,task:'Определить приём в каждой строке: аллитерация, ассонанс или звукоподражание. Записать повторяющиеся звуки и сказать, что они передают.',
  obr:'«Шипенье пенистых бокалов»: [ш], [п], [н\'] — аллитерация; шипение пены.',
  body:'1. Вечор, ты помнишь, вьюга злилась, / На мутном небе мгла носилась; (А. С. Пушкин, «Зимнее утро») 2. По стёклам тихо стекали слезливые струйки... (В. Г. Короленко, «Таланты») 3. Море шепталось по-прежнему с берегом, и ветер всё так же носил его шёпот по степи. (М. Горький, «Макар Чудра») 4. Пышные гнутся макушки, / Млея в весеннем соку; / Где-то вдали от опушки / Будто бы слышно: ку-ку. (А. А. Фет, «Кукушка») 5. Ши-ши-ши — шептали камыши, шорох шёл по всему саду.',
  key:'1. [л], [с] в словах «вьюга злилась», «мгла носилась» — аллитерация; передаёт свист и кружение метели. 2. [с], [т], [к], [л] («по стёклам тихо стекали слезливые струйки») — аллитерация; слышны стук и скольжение капель. 3. [ш], [п], [с] («шепталось», «шёпот», «степи») — аллитерация; слышен шёпот моря. 4. «Ку-ку» — звукоподражание (крик кукушки); в начале строфы повторяются [п], [к], [ш] («пышные гнутся макушки») — аллитерация, рисующая шорох листвы. 5. [ш] — аллитерация; передаёт шуршание камыша; «ши-ши-ши» — звукоподражание.'},
 {n:4,l:1,st:2,task:'Сравнить две строки с одинаковым смыслом. В какой звукопись передаёт образ лучше? Выписать повторяющиеся звуки и объяснить выбор.',
  obr:'Шорох камыша: а) «Ши-ши-ши — шептали камыши»; б) «Камыши тихо качались». В (а) повторяются [ш], [щ\']: слышен шорох.',
  body:'1. а) Ши-ши-ши — шептали камыши. б) Камыши тихо качались. 2. а) Гром грохотал, гремел, грохотал над горой. б) Над горой был гром. 3. а) Луна лила лунный свет на ленивые луга. б) Луна освещала поля. 4. а) Жук жужжит и вьётся над жасмином. б) Жук летает над цветами.',
  key:'1. (а): [ш], [щ\'] — шорох. 2. (а): [г], [р] — раскаты грома; в (б) звукописи нет. 3. (а): [л] — плавное, тихое сияние; в (б) просто сообщение. 4. (а): [ж] и слова «жужжит», «жук» — гудение; в (б) звукописи нет. Вывод: в вариантах (а) звуки повторяются и усиливают смысл слов, в вариантах (б) — не повторяются.'},
 {n:5,l:1,st:2,task:'Выписать из предложений слова-звукоподражания и сказать, чей или какой звук они передают. Придумать к каждому предложению нейтральное слово-замену и сравнить.',
  obr:'«Ку-ку», — донеслось из лесу. Звукоподражание: ку-ку (кукушка). Замена: «из лесу донёсся голос птицы» — теряется звучание.',
  body:'1. За стеной тикали часы: тик-так, тик-так. 2. Дверь хлопнула, и в коридоре зашуршали шаги. 3. Над лугом жужжали пчёлы, а в тени мяукала кошка. 4. Во дворе кукарекал петух, ему в ответ залаял щенок: гав-гав. 5. Сорока застрекотала на ветке: тррр-тррр. 6. Мяч ударился о стену — бух! — и откатился в траву.',
  key:'1. тик-так (часы). 2. хлопнула, зашуршали (хлоп — удар двери, шорох шагов). 3. жужжали (пчёлы), мяукала (кошка). 4. кукарекал (петух), гав-гав (щенок). 5. застрекотала, тррр-тррр (сорока). 6. бух (удар мяча). Замена нейтральным словом («часы показывали время», «дверь закрыли») убирает звук: звукоподражание позволяет «услышать» события.'},
 {n:6,l:1,st:3,task:'Найти в строках повторы звуков. Определить приём (аллитерация или ассонанс) и что он передаёт. Для каждой строки записать, чем подтверждается вывод (какими словами по смыслу).',
  obr:'«Ревёт ли зверь в лесу глухом»: повтор [р] — аллитерация, рёв; подтверждается словом «ревёт».',
  body:'1. Ревёт ли зверь в лесу глухом, / Трубит ли рог, гремит ли гром, / Поёт ли дева за холмом — / На всякий звук / Свой отклик в воздухе пустом / Родишь ты вдруг. (А. С. Пушкин, «Эхо») 2. Певучесть есть в морских волнах, / Гармония в стихийных спорах, / И стройный мусикийский шорох / Струится в зыбких камышах. (Ф. И. Тютчев, «Певучесть есть в морских волнах») 3. В пене гнева стонут волны, с ветром споря. (М. Горький, «Песня о Буревестнике») 4. Лёгкий лунный свет лился на ленивые лужайки. 5. Дорога дрожала, и дрожь отзывалась в дрожащей дали.',
  key:'1. [р] (ревёт, трубит, рог, гремит, гром) — аллитерация: рёв и грохот; [л] («поёт ли дева за холмом») — мягкий плавный звук, образ покоя. 2. [с], [ш], [з] — аллитерация: шорох камыша («шорох», «струится»). 3. [в], [н], [п], [с] («в пене гнева стонут волны, с ветром споря») — аллитерация: гул и ропот волн; подтверждается словами «стонут», «споря». 4. [л] — аллитерация: плавное мягкое сияние. 5. [д], [р], [ж] — аллитерация: передаёт дрожь.'},
 {n:7,l:1,st:3,task:'Прочитать вслух отрывки. 1) Найти повторяющиеся звуки в каждом. 2) Назвать, что они «рисуют». 3) Выписать слова, которые напрямую называют этот звук или движение.',
  obr:'«Бегут и будят сонный брег»: [б], [г] повторяются — быстрый бег воды; слово «бегут».',
  body:'1. Ещё в полях белеет снег, / А воды уж весной шумят — / Бегут и будят сонный брег, / Бегут и блещут и гласят. (Ф. И. Тютчев, «Весенние воды») 2. Девушка пела в церковном хоре / О всех усталых в чужом краю, / О всех кораблях, ушедших в море, / О всех, забывших радость свою. (А. А. Блок, «Девушка пела в церковном хоре»)',
  key:'1. [б], [г] («бегут, будят, брег, блещут, гласят») — аллитерация и лексический повтор «бегут»; бег весенних ручьёв, звон воды. Слова «шумят», «блещут», «гласят» называют звук и блеск. 2. Гласные [о], [у] («о всех усталых в чужом краю», «о всех кораблях, ушедших в море») тянутся, как напев; слово «пела» называет звук, повтор «о всех» поддерживает протяжность.'},
 {n:8,l:1,st:3,task:'Сравнить две строки Пушкина. Доказать, что звукопись в одной передаёт свист и кружение, а в другой — лёгкое движение. Записать повторяющиеся звуки.',
  obr:'«Вьюга злилась»: [л], [с] — свист; «Ветер... гуляет»: [г], [л], [н] — мягкий, плавный ход.',
  body:'1. Вечор, ты помнишь, вьюга злилась, / На мутном небе мгла носилась; (А. С. Пушкин, «Зимнее утро») 2. Ветер по морю гуляет / И кораблик подгоняет; / Он бежит себе в волнах / На поднятых парусах. (А. С. Пушкин, «Сказка о царе Салтане»)',
  key:'1. [л], [с] в словах «злилась», «носилась» — свист и кружение метели. 2. [г], [л], [н], [п] («Ветер по морю гуляет / И кораблик подгоняет») — мягкие, плавные звуки; движение лёгкое, ровное. Вывод: разные звуки в сочетании со смыслом слов рисуют разные картины.'},
 {n:9,l:1,st:3,task:'Разобрать строки по шагам: прочитать вслух, найти повторяющиеся звуки, назвать приём, определить образ, проверить связь со смыслом.',
  obr:'«Ветер по морю гуляет / И кораблик подгоняет»: [г], [л], [н] повторяются; образ — лёгкое движение; слова «гуляет», «подгоняет».',
  body:'1. Ветер по морю гуляет / И кораблик подгоняет; / Он бежит себе в волнах / На поднятых парусах. (А. С. Пушкин, «Сказка о царе Салтане») 2. Где-то за пределами освещённого пространства береговой лес бормочет и по временам шевелит беспокойно спящими ветвями... (В. Г. Короленко, «В пустынных местах») 3. Точно в действительности слышно, как и море стонет и в нём челночок поглощённый бьётся. (Н. С. Лесков, «Очарованный странник»)',
  key:'1. [г], [л], [н], [п] — аллитерация; мягкое, плавное движение кораблика. 2. [б], [р], [м] в «бормочет», «беспокойно» — глуховатое бормотание леса. 3. [т], [н], [м] в «стонет», «челночок», «поглощённый» — стон и глухие удары волны. Во всех случаях вывод подтверждён словами «гуляет», «бормочет», «стонет».'},
 {n:10,l:1,st:4,task:'Найти в текстах звукопись, которая сделана намеренно, и ту, которая случайна. Объяснить различие: что должно быть, чтобы повтор звуков считать приёмом?',
  body:'1. Ещё в полях белеет снег, / А воды уж весной шумят — / Бегут и будят сонный брег, / Бегут и блещут и гласят. (Ф. И. Тютчев, «Весенние воды») 2. Вчера в вечернем вестнике вышла важная весть о выставке. 3. Мы хотим мирно мыть мамины миски. 4. Я свистну, и ко мне послушно, робко / Вползёт окровавленное злодейство… (А. С. Пушкин, «Скупой рыцарь»)',
  key:'1. Намеренно: [б], [г] («Бегут и будят сонный брег, / Бегут и блещут и гласят») — передаёт бег воды. 2. Повтор [в] случаен: нет образа, он только отвлекает. 3. Повтор [м] случаен (скороговорка), образа нет. 4. «Вползёт окровавленное злодейство»: [в], [л], [з] — звуки вязкого, ползущего движения; слово «вползёт» подтверждает. Вывод: звукопись — приём, когда повтор заметен, связан со смыслом слов и создаёт образ; случайный повтор — недостаток.'},
 {n:11,l:1,st:4,task:'Определить, что в каждом примере: звукопись, звукоподражание, лексический повтор или рифма. В одном примере может быть несколько явлений — выписать все и назвать главное.',
  body:'1. Ку-ку, ку-ку, — звенело в роще. 2. Люблю, люблю, люблю эту рощу! 3. Мороз и солнце; день чудесный! / Ещё ты дремлешь, друг прелестный — (А. С. Пушкин, «Зимнее утро») 4. Часы на стене: тик-так, тик-так.',
  key:'1. «Ку-ку» — звукоподражание (повторено, поэтому есть и лексический повтор). 2. Лексический повтор «люблю» (не звукопись: повторяются слова). 3. Рифма «чудесный — прелестный» (концы строк); звукописи как главного приёма нет. 4. «Тик-так» — звукоподражание (стук часов), повторено.'},
 {n:12,l:1,st:4,task:'Найти ошибку в рассуждении ученика и исправить. Для каждого утверждения записать, верно ли оно и почему.',
  body:'1. «В строке „Люблю, люблю, люблю“ есть аллитерация, потому что повторяется слог „лю“». 2. «Слово „жужжать“ — это ассонанс». 3. «Чтобы найти ассонанс, достаточно посчитать буквы». 4. «Звук [р] всегда передаёт грохот».',
  key:'1. Неверно: повторяются слова — это лексический повтор (или анафора), а не звукопись. 2. Неверно: «жужжать» — звукоподражание (слово воспроизводит звук). 3. Неверно: считать нужно звуки, а не буквы («щ» = [щ\'], «ц» = [ц], «ь» звука не даёт). 4. Неверно: [р] передаёт грохот и рёв там, где такие слова есть («ревёт», «гремит»); в строке о тихом утре он ничего такого не изображает — образ зависит от смысла слов.'},
 {n:13,l:1,st:5,os:'сочинение',task:'Написать сочинение-миниатюру «Звуки города» (5–7 предложений). Использовать аллитерацию или ассонанс, одно звукоподражание, одну строку с лексическим повтором. Подчеркнуть звукопись и объяснить, что она рисует.',
  key:'Проверить: 5–7 предложений; не менее одного приёма звукописи (аллитерации или ассонанса), одно слово-звукоподражание, не путающееся с обычным словом; подчёркнуты повторяющиеся звуки; под текстом 2–3 предложения о том, что они «рисуют» (например, «повтор [ш] передаёт шорох шин»). Образец: Шуршат шины, шипят тормоза, шепчутся шаги прохожих. Где-то тикает табло: тик-так, тик-так. Город шумит и шумит. Комментарий: [ш] изображает шелест и шипение уличного движения; «тик-так» — звукоподражание; «шумит и шумит» — лексический повтор, усиливающий ощущение сплошного шума.'},
 {n:14,l:1,st:5,os:'работа с текстом',task:'Выбрать любое стихотворение из учебника литературы (8–12 строк). Найти в нём звукопись и составить таблицу из трёх столбцов: «повторяющиеся звуки (в квадратных скобках)» — «приём» — «что рисуют звуки и чем подтверждается». Не меньше четырёх строк таблицы; одно наблюдение должно быть о том, что повтор случаен и приёмом не является. В конце — вывод в 2–3 предложения.',
  key:'Проверить: выбрано стихотворение; в таблице не меньше четырёх строк; звуки названы именно звуками, а не буквами; приём определён верно (аллитерация или ассонанс; слово-звукоподражание отмечено отдельно); для каждой строки указано, что звуки рисуют, и приведены слова, подтверждающие вывод; есть одно наблюдение о случайном повторе; вывод опирается на таблицу. Образец строки таблицы: [ш], [п], [н\'] («Шипенье пенистых бокалов») — аллитерация — шипение пены; подтверждается словом «шипенье».'},
// ── Урок 2. Тропы: перенос значения
 {n:15,l:2,st:1,task:'Прочитать словосочетания. Выписать те, где слово употреблено в переносном значении, и сказать, по сходству (метафора) или по связи (метонимия) перенесено название.',
  obr:'медовый голос — метафора (голос приятный, как мёд).',
  body:'медовый голос, золотое кольцо, читать Пушкина, весь класс притих, железная воля, железный гвоздь, нос лодки, выпить чашку чая, шляпка гриба, шапка на голове',
  key:'Переносное значение: медовый голос (метафора), читать Пушкина (метонимия: автор — книги), весь класс притих (метонимия: место — ученики), железная воля (метафора), нос лодки (метафора), выпить чашку чая (метонимия: посуда — содержимое), шляпка гриба (метафора). Прямое значение: золотое кольцо, железный гвоздь, шапка на голове.'},
 {n:16,l:2,st:2,task:'Найти в предложениях олицетворения. Выписать слова, которыми неживое наделено свойствами человека, и сказать, какой образ получился.',
  obr:'«Тёплый ветер гуляет по траве»: гуляет — ветер как человек на прогулке; образ лёгкого, свободного ветра.',
  body:'1. Тёплый ветер гуляет по траве, гнёт деревья и поднимает пыль. (А. П. Чехов, «День за городом») 2. Ветерок беспокойно содрогался в тёмных деревьях, и где-то далеко за небосклоном, словно про себя, ворчал гром сердито и глухо. (И. С. Тургенев, «Первая любовь») 3. Было жарко от работы, и шея как-то распрямилась, на ладонях сладко ныли свежие мозоли, и день улыбался. (Л. Н. Андреев, «Призраки») 4. Звёзды ласково мигали лучами, проникавшими до самого его сердца. (В. М. Гаршин, «Красный цветок») 5. Где-то за пределами освещённого пространства береговой лес бормочет и по временам шевелит беспокойно спящими ветвями... (В. Г. Короленко, «В пустынных местах») 6. Днём и ночью идёт дождь, голые деревья плачут, ветер сыр и холоден. (А. П. Чехов, «Выигрышный билет»)',
  key:'1. гуляет — ветер как человек на прогулке. 2. ворчал (гром), содрогался (ветерок), «словно про себя» — гром как недовольный старик. 3. день улыбался — светлый, радостный день, как человек. 4. ласково мигали — звёзды смотрят заботливо. 5. лес бормочет, шевелит ветвями — лес как живой, спящий. 6. деревья плачут — осенняя печаль.'},
 {n:17,l:2,st:2,task:'Определить троп в выделенном слове или выражении: метафора, олицетворение, метонимия или синекдоха. Обосновать (по сходству, по связи, по количеству).',
  obr:'Весь театр встал: метонимия (место — люди).',
  body:'1. Весь город говорит, смеётся, и только он один ничего не знает и не видит… (А. П. Чехов, «Три сестры») 2. Мы любим читать Лермонтова. 3. Он выучил Крылова наизусть. 4. Золотой август стоял над деревней. 5. На поле колосилось море пшеницы. 6. В классе нет ни одной живой души.',
  key:'1. «Весь город говорит» — метонимия: город вместо жителей. 2. Метонимия: автор вместо его книг. 3. Метонимия: автор вместо басен. 4. «Золотой» — метафора: август яркий, как золото. 5. «Море пшеницы» — метафора: колосья колышутся, как волны. 6. «Живая душа» — синекдоха: «душа» вместо «человек».'},
 {n:18,l:2,st:2,task:'Разобрать каждую метафору: что на что похоже? Записать «развёрнутый» вариант со словом «как».',
  obr:'Медовый голос: голос приятный, как мёд.',
  body:'1. Она вошла глубоко в море хлеба, тяжело опустилась там на землю и долго неподвижно лежала на земле. (М. Горький, «Скуки ради») 2. Стройные пальмы, латании и филодендроны отражаются в бесконечных зеркалах и, образуя океан зелени, уносят ваше воображение в страну (А. П. Чехов, «Идиллия») 3. Снег загорелся широким серебряным полем и весь обсыпался хрустальными звёздами. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 4. Солнце легло спать и укрылось багряной золотой парчой, и длинные облака, красные и лиловые, сторожили его покой, протянувшись по небу. (А. П. Чехов, «В овраге») 5. Каменное лицо у сторожа. 6. Стальные нервы у лётчика.',
  key:'1. Море хлеба: поле колышется, как море. 2. Океан зелени: безбрежные заросли, как океан. 3. Серебряное поле, хрустальные звёзды: снег блестит, как серебро, снежинки как хрусталь. 4. Багряная золотая парча: закатные облака, как дорогая ткань. 5. Лицо неподвижное, как камень. 6. Нервы крепкие, как сталь.'},
 {n:19,l:2,st:3,task:'Определить, на чём основан перенос в каждом примере: сходство, связь, количество, описание вместо названия. Назвать троп.',
  obr:'Царь зверей: описание вместо названия — перифраза.',
  body:'1. У себя принимала она весь город, наблюдая строгий этикет и не узнавая никого в лицо. (А. С. Пушкин, «Пиковая дама») 2. …больше всего береги и копи копейку: эта вещь надёжнее всего на свете. (Н. В. Гоголь, «Мёртвые души») 3. Автор «Мцыри» работал над романом. 4. Город на Неве встретил гостей белыми ночами. 5. Он выпил две кружки молока и пошёл спать. 6. Все мы глядим в «Эйнштейны» (свой текст: каждый считает себя Эйнштейном).',
  key:'1. «Весь город» — метонимия (город — жители). 2. «Копейка» вместо «деньги» (видовое вместо родового) — синекдоха. 3. Описание вместо названия — перифраза (Лермонтов). 4. Описание вместо названия — перифраза (Санкт-Петербург). 5. «Две кружки» вместо «молока из кружек» — метонимия. 6. Множественное число вместо единственного — синекдоха.'},
 {n:20,l:2,st:3,task:'Определить, ирония это или нет. Если ирония — объяснить, что на самом деле думает говорящий.',
  obr:'«Хороша педагогия, нечего сказать»: ирония — на самом деле осуждение.',
  body:'1. Ну, одолжили; нечего сказать, утешили! (Ф. М. Достоевский, «Бобок») 2. Спасибо, что помог донести сумки до дома. 3. V / Мы все учились понемногу / Чему-нибудь и как-нибудь, / Так воспитаньем, слава богу, / У нас немудрено блеснуть. (А. С. Пушкин, «Евгений Онегин») 4. Дождь шёл три дня, и пруд поднялся на полметра. 5. Ну и молодец: снова забыл тетрадь дома! 6. Умница, как хорошо ответила у доски!',
  key:'1. Ирония: «утешили» значит «огорчили». 2. Не ирония: искренняя благодарность. 3. Ирония: «слава богу» и «немудрено блеснуть» — насмешка над поверхностным воспитанием. 4. Не ирония: нейтральное сообщение. 5. Ирония: «молодец» и «умница» говорят о том, что человек подвёл. 6. Не ирония: искренняя похвала ученице.'},
 {n:21,l:2,st:3,task:'Определить: метафора, олицетворение или метонимия. Для каждого примера записать проверку («как», пропущенное слово или человеческое действие).',
  obr:'Медовый голос — метафора (голос, как мёд).',
  body:'1. Дожидаясь отплытия, я бродил по старым улицам, по набережной, катался в лодке по морю, а море было синее, светлое, море смеялось. (К. Д. Бальмонт, «В странах Солнца») 2. Извергая клубы тяжёлого, серого дыма, пассажирский поезд, как огромное пресмыкающееся, исчезал в степной дали, в жёлтом море хлебов. (М. Горький, «Скуки ради») 3. Класс отправился на экскурсию. 4. Он любит читать Гоголя. 5. Они бежали низко и быстро - и скоро, точно дым, затуманивали солнце. (И. А. Бунин, «Антоновские яблоки») 6. Холодный воздух пробирал до костей.',
  key:'1. Море смеялось — олицетворение (смеяться умеет человек). 2. «Как огромное пресмыкающееся» — сравнение; «море хлебов» — метафора: хлеба колышутся, как море. 3. Метонимия: класс вместо учеников; проверка — «ученики класса». 4. Метонимия: книги Гоголя. 5. «Точно дым» — сравнение; «затуманивали» — слово в переносном значении. 6. «Пробирал» — олицетворение (холод действует, как живое существо).'},
 {n:22,l:2,st:3,task:'В каждом тексте найти развёрнутую метафору или цепочку олицетворений. Записать слова, из которых строится образ, и сказать, какой образ создан.',
  obr:'Зима «поёт», «аукает», «баюкает»: цепочка олицетворений, образ доброй хозяйки леса.',
  body:'1. Вот охватывает ветер стаи волн объятьем крепким и бросает их с размаху в дикой злобе на утёсы, разбивая в пыль и брызги изумрудные громады. (М. Горький, «Песня о Буревестнике») 2. Поёт зима — аукает, / Мохнатый лес баюкает / Стозвоном сосняка. (С. А. Есенин, «Поёт зима — аукает…») 3. Гром заворчал в туче, как дикий зверь, удивлённый бесстрашием ливийца-укротителя, когда он безоружный подходит к нему с ясным взглядом. (В. Г. Короленко, «Тени»)',
  key:'1. Ветер «охватывает объятьем», «бросает», «в дикой злобе» — развёрнутая метафора: ветер как борец или хищник, волны как стая. 2. «Поёт», «аукает», «баюкает» — олицетворение зимы и леса; образ ласковой хозяйки зимы. 3. Гром «заворчал», «как дикий зверь, удивлённый бесстрашием» — олицетворение и сравнение: гром как зверь, а герой как укротитель.'},
 {n:23,l:2,st:3,task:'Различить языковые (стёртые) и авторские метафоры. Выписать первые и вторые.',
  obr:'Нос лодки — языковая (стёртая) метафора.',
  body:'1. нос лодки; 2. ножка стола; 3. багряные листья осени, обтянувшие деревья; 4. хвост поезда; 5. кружевная пена на песке; 6. лист бумаги; 7. ручка двери; 8. «Закат багряной золотой парчой укрылся».',
  key:'Языковые (стёртые): нос лодки, ножка стола, хвост поезда, лист бумаги, ручка двери. Авторские: багряные листья, обтянувшие деревья; кружевная пена на песке; закат укрылся парчой. Ориентир: языковая метафора стала названием, образа не создаёт; авторская даёт новый, неожиданный образ.'},
 {n:24,l:2,st:4,task:'Найти и назвать все тропы в предложениях. Объяснить, на чём основан каждый.',
  body:'1. Дорога вилась лентой, а на горизонте стояла серебряная стена леса. 2. Мы всю зиму читали Лермонтова, и школа гудела от стихов. 3. Я свистну, и ко мне послушно, робко / Вползёт окровавленное злодейство… (А. С. Пушкин, «Скупой рыцарь») 4. Он говорил так тихо, что было слышно, как летит муха.',
  key:'1. «Вилась лентой» — сравнение (творительный падеж) или метафора; «стена леса» — метафора; «серебряная» — эпитет. 2. «Читали Лермонтова» — метонимия (автор — книги); «школа гудела» — метонимия (место — люди) с олицетворением. 3. «Вползёт» — олицетворение: злодейство ползёт, как зверь; «окровавленное» — эпитет. 4. Гипербола: слышно, как летит муха, — очень тихо.'},
 {n:25,l:2,st:4,task:'Разграничить троп и его «подделку»: в каждой паре один пример содержит троп, другой — прямое значение. Выписать пример с тропом и назвать троп.',
  body:'1. а) Рука болит. б) Золотые руки у мастера. 2. а) Стальная балка перекрытия выдержит вес всего этажа и ещё нескольких тонн груза. б) Стальная воля. 3. а) В классе тихо. б) Весь класс притих. 4. а) Гора спит. б) Дед спит в кресле. 5. а) Читал Толстого. б) Читал романы.',
  key:'1. б — метафора. 2. б — метафора. 3. б — метонимия (класс — ученики; в «а» слово «класс» — помещение). 4. а — олицетворение (гора не может спать). 5. а — метонимия (Толстой — книги). В остальных случаях слова употреблены в прямом значении.'},
 {n:26,l:2,st:4,task:'Определить, ирония или прямое высказывание. Если ирония — переписать фразу так, чтобы смысл стал прямым.',
  body:'1. «Вот так помощник! Всю работу переделывать пришлось». 2. «Вы очень помогли мне: теперь я знаю, как решить задачу». 3. «Какая погода! Зонт промок, ботинки тоже». 4. «Отлично, мы опоздали на последний автобус и идём пешком!» 5. «Чудесно придумано: сначала всё сломать, а потом удивляться!» 6. «Вот это погода: ни дождя, ни тумана, только солнце — идеально для прогулки».',
  key:'1. Ирония: на самом деле «плохой помощник». Прямо: «Ты не помог». 2. Прямое высказывание: говорящий благодарен. 3. Ирония: «какая погода» — на деле плохая. 4. Ирония: «отлично» значит «плохо, что опоздали». 5. Ирония: «чудесно» значит «глупо». 6. Прямое высказывание: погода действительно хорошая.'},
 {n:27,l:2,st:5,task:'Задание для абитуриентов. Прочитать текст. Указать номера верных утверждений.',
  body:'Текст: (1) Горы молчали. (2) Лес стоял, как стена. (3) Над перевалом проплыла серебряная туча — она шла медленно, словно старая птица. (4) Лес что-то шептал листвой, но слов не разобрать. (5) Я читал Некрасова при свече.<br>Утверждения: 1) В предложении 1 олицетворение. 2) В предложении 2 метафора. 3) В предложении 3 есть и эпитет, и сравнение. 4) В предложении 4 олицетворение. 5) В предложении 5 метонимия. 6) В предложении 5 слово «свеча» употреблено в переносном значении.',
  key:'Верные утверждения: 1, 3, 4, 5. Пояснения: 2 — неверно: «как стена» — сравнение (есть «как»), а не метафора; 6 — неверно: «свеча» употреблено в прямом значении; 5 — верно: «читал Некрасова» — автор вместо книг (метонимия); 1 — верно: горы «молчали»; 3 — верно: «серебряная» — эпитет, «словно старая птица» — сравнение; 4 — верно: ветер «шептал».'},
 {n:28,l:2,st:5,os:'сочинение',task:'Написать описание зимнего утра (6–8 предложений), используя: одно олицетворение, одну развёрнутую метафору, одну метонимию, одну перифразу. Выписать их под текстом и подписать, что есть что.',
  key:'Проверить: 6–8 предложений; олицетворение (например, «зима поёт, мороз рисует»); развёрнутая метафора (образ в нескольких словах: «снег — белая скатерть, на которую утро расставило серебряную посуду инея»); метонимия («весь двор вышел кататься»); перифраза («хозяйка зимы вместо „метель“» или «царь морозов»). Образец: Зима расписала окна серебряными узорами. Снег лежал белой скатертью, на которой утро расставило хрустальную посуду инея. Весь двор вышел на санках. Хозяйка зимы кружила над крышами, и деревья кланялись ей до земли.'}
,
// ── Урок 3. Эпитет, сравнение, гипербола и литота
 {n:29,l:3,st:1,task:'В каждой паре найти сочетание с эпитетом (образным определением) и сочетание с обычным определением. Записать эпитеты и сказать, какой образ они создают.',
  obr:'Деревянный стол — обычное определение; медовый голос — эпитет (голос приятный, сладкий).',
  body:'1. деревянный стол — медовый голос; 2. зимний день — хрустальный день над замёрзшим прудом; 3. стальные нервы — стальной гвоздь; 4. рыжая осень на аллеях парка — золотое кольцо на столе; 5. школьный двор — весёлый двор; 6. жадный огонь — горячий огонь; 7. тяжёлое молчание повисло в комнате — тяжёлый чемодан; 8. каменное сердце — каменный дом',
  key:'Эпитеты: медовый голос (приятный, как мёд); хрустальный день (прозрачный, звонкий); стальные нервы (крепкие, как сталь); рыжая осень (яркая, как лисий мех); весёлый двор (двор, который «радуется»); жадный огонь (огонь «пожирает», как жадный человек); тяжёлое молчание (молчание давит); каменное сердце (бессердечие). Обычные определения: деревянный стол, зимний день, стальной гвоздь, золотое кольцо, школьный двор, горячий огонь, тяжёлый чемодан, каменный дом.'},
 {n:30,l:3,st:2,task:'Выписать из предложений эпитеты. Отметить, чем выражен каждый: прилагательным, причастием, наречием или существительным-приложением. Указать одно обычное определение, которое эпитетом не является.',
  obr:'Холодным, равнодушным взглядом: холодным, равнодушным — прилагательные.',
  body:'1. Ночь легла на город холодным, равнодушным взглядом. 2. Тихо-тихо дремал сад, укутанный белой дымкой, и над ним медленно плыли первые звёзды. 3. Мороз-старик обошёл деревню и расписал окна. 4. Ручей весело бежит. 5. Угрюмо стояли ели. 6. Лошадь-труженица тянула баржи вверх по течению, не зная отдыха ни днём, ни ночью.',
  key:'1. холодным, равнодушным — прилагательные. 2. тихо-тихо — наречие; укутанный — причастие; «белой» — обычное определение (дымка белая по цвету). 3. Мороз-старик — приложение. 4. весело — наречие. 5. угрюмо — наречие. 6. Лошадь-труженица — приложение. Обычное определение, не эпитет: «белой» (предложение 2).'},
 {n:31,l:3,st:2,task:'Определить, как выражено каждое сравнение: творительным падежом, союзом, словом «подобный/похожий» или сравнительной степенью. Записать, что с чем сравнивается.',
  obr:'«Ковром шёлковым стелется» (метель): творительный падеж; метель — ковёр.',
  body:'1. А по двору метелица / Ковром шёлковым стелется, / Но больно холодна. (С. А. Есенин, «Поёт зима — аукает…») 2. Солнце светит кругом яркими лучами, и лучи разбивают, как стекло, тонкий лёд. (Ф. М. Достоевский, «Бедные люди») 3. На другой день переехали мы по гладкому, как зеркало, льду страшную для меня Волгу. (С. Т. Аксаков, «Детские годы Багрова-внука») 4. Ночь светлее дня. 5. Его голос, подобный колокольному звону, разносился по долине, где не было ни звука. 6. Туман похож на молоко.',
  key:'1. Творительный падеж («ковром»): метель — ковёр. 2. Союз «как»: лучи разбивают лёд, как стекло (лёд хрупок). 3. Союз «как»: лёд гладкий, как зеркало. 4. Сравнительная степень («светлее дня»): ночь — день. 5. Слово «подобный»: голос — колокольный звон. 6. Слово «похож»: туман — молоко.'},
 {n:32,l:3,st:2,task:'Преобразовать сравнение в метафору и метафору в сравнение. Записать результат и сказать, что в результате изменилось.',
  obr:'Берёзы стоят, как свечки → свечки берёз. Метафора короче, но образ «спрятан».',
  body:'1. Рыжая осень → ... 2. Облака, как корабли, плывут по небу → ... 3. Её голос как мёд → ... 4. Железная воля → ... 5. Снег лежит, как ковёр → ... 6. Туман — молочная река → ...',
  key:'1. Осень, как лисий мех; осень яркая и тёплая. 2. Облака-корабли плывут по небу; сравнение превращается в метафору (нет «как»). 3. Медовый голос; сравнение стало эпитетом. 4. Воля крепкая, как железо. 5. Ковёр снега; снежный ковёр. 6. Туман, как молочная река, течёт по лугу. После преобразования метафора короче и образнее, сравнение яснее показывает, что с чем сопоставлено.'},
 {n:33,l:3,st:3,task:'Определить: гипербола, литота-преуменьшение или литота-отрицание (двойное отрицание вместо утверждения). Объяснить.',
  obr:'«Мужичок с ноготок» — литота-преуменьшение («с ноготок» — очень маленький).',
  body:'1. Оно пылало так ярко, как солнце, и ярче солнца, и весь лес замолчал, освещённый этим факелом великой любви к людям, а тьма разлетелась от света его и там, глубоко в лесу, дрожащая, пала в гнилой зев болота. (М. Горький, «Старуха Изергиль») 2. Он так часто и грустно говорил: было, была, бывало, точно прожил на земле сто лет, а не одиннадцать. (М. Горький, «В людях») 3. Лошадку ведёт под уздцы мужичок / В больших сапогах, в полушубке овчинном, / В больших рукавицах... а сам с ноготок! (Н. А. Некрасов, «Крестьянские дети») 4. Ты хорошая, добрая, и ты не глупая, ты поймёшь... (А. П. Чехов, «Анюта») 5. Мнение сие не без основания, как увидим ниже. (А. С. Пушкин, «История Пугачёва») 6. Он ростом был с ноготок.',
  key:'1. Гипербола («ярче солнца», «весь лес замолчал»). 2. Гипербола («точно прожил сто лет, а не одиннадцать»). 3. Литота-преуменьшение («с ноготок»). 4. Литота-отрицание («не глупая» — умная). 5. Литота-отрицание («не без основания» — с основанием). 6. Литота-преуменьшение (очень маленький).'},
 {n:34,l:3,st:3,task:'Заменить литоты-отрицания прямыми утверждениями. Сравнить: что теряется при замене?',
  obr:'«Не без зависти» → с завистью. Теряется оттенок сдержанности.',
  body:'1. Его слушали с интересом и не без зависти. (М. Горький, «Бывшие люди») 2. Кузнец не без робости отворил дверь и увидел Пацюка, сидевшего на полу по-турецки… (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 3. Я удивляюсь, как с её умом, – она ведь не глупа, – не видеть, как она смешна. (Л. Н. Толстой, «Анна Каренина») 4. Мнение сие не без основания, как увидим ниже. (А. С. Пушкин, «История Пугачёва») 5. Он не лишён способностей. 6. Нельзя не согласиться с этим выводом.',
  key:'1. С завистью. 2. С робостью. 3. Она умна. 4. Мнение имеет основание. 5. Он способный человек. 6. Следует согласиться с этим выводом. При замене пропадает сдержанность и мягкость: двойное отрицание звучит осторожнее и вежливее прямого утверждения.'},
 {n:35,l:3,st:3,task:'Выписать из отрывков эпитеты. Для каждого сказать, какой образ создан и что показывает отношение автора.',
  obr:'«Славная осень» (Некрасов): славная — эпитет, автор любуется.',
  body:'1. Есть женщины в русских селеньях / С спокойною важностью лиц, / С красивою силой в движеньях, / С походкой, со взглядом цариц. (Н. А. Некрасов, «Мороз, Красный нос») 2. Уж небо осенью дышало, / Уж реже солнышко блистало, / Короче становился день, / Лесов таинственная сень / С печальным шумом обнажалась, / Ложился на поля туман, / Гусей крикливых караван / Тянулся к югу: приближалась / Довольно скучная пора; / Стоял ноябрь уж у двора. (А. С. Пушкин, «Евгений Онегин») 3. Печальная берёза / У моего окна, / И прихотью мороза / Разубрана она. (А. А. Фет, «Печальная берёза») 4. Кругом с тоской глубокою / Плывут в страну далёкую / Седые облака. (С. А. Есенин, «Поёт зима — аукает…»)',
  key:'1. Спокойною (важностью), красивою (силой): образ величавой женщины, автор восхищается. 2. Таинственная (сень), печальным (шумом), крикливых (гусей), скучная (пора): осень с печалью и скукой. 3. Печальная (берёза): берёза как грустная женщина. 4. Тоской глубокою, страну далёкую, облака седые: образ усталой, глубокой зимы.'},
 {n:36,l:3,st:3,task:'Для каждого сравнения записать: что с чем сравнивается и каким способом выражено сравнение. Назвать то, чем эти предметы похожи.',
  obr:'«Горные хребты, причудливые, как мечты»: хребты — мечты; союз «как»; сходство — причудливость.',
  body:'1. Я видел горные хребты, / Причудливые, как мечты… (М. Ю. Лермонтов, «Мцыри») 2. Ну ж был денёк! Сквозь дым летучий / Французы двинулись, как тучи, / И всё на наш редут. (М. Ю. Лермонтов, «Бородино») 3. Бывало, если вечер тих, -- озеро покойно; на деревах, что по берегу росли, не шелохнёт, вода неподвижна, словно зеркало. (Ф. М. Достоевский, «Бедные люди») 4. Она уложила их, как малых детей, одного — на полу, другого — на койке, и, когда они захрапели, вышла в сени. (М. Горький, «В людях») 5. Они бежали низко и быстро - и скоро, точно дым, затуманивали солнце. (И. А. Бунин, «Антоновские яблоки») 6. Нева металась, как больной / В своей постеле беспокойной. (А. С. Пушкин, «Медный всадник»)',
  key:'1. Хребты — мечты; «как»; причудливость. 2. Французы — тучи; «как»; многочисленность и грозное движение. 3. Вода — зеркало; «словно»; неподвижность и гладкость. 4. Гости — малые дети; «как»; беспомощность. 5. Тучи — дым; «точно»; лёгкость, неопределённость. 6. Нева — больной в постели; «как»; беспокойство, метание.'},
 {n:37,l:3,st:3,task:'Подобрать к каждому слову по два эпитета (образных определения, а не обычных). Составить с одним из сочетаний предложение. Объяснить, какой образ создан.',
  obr:'Ночь: бархатная, звёздная — «Бархатная ночь легла на сад». Образ мягкой, тёмной ночи.',
  body:'ночь, ручей, голос, костёр, тишина, туман, дорога, облако',
  key:'Примерные эпитеты: ночь — бархатная, настороженная; ручей — весёлый, говорливый; голос — серебряный, надтреснутый; костёр — жадный, трескучий; тишина — звенящая, тяжёлая; туман — молочный, густой; дорога — извилистая, усталая; облако — пушистое, ленивое. Проверка: убрать определение — образ должен пропасть. Обычные определения («зимний», «деревянный», «школьный») не подходят.'},
 {n:38,l:3,st:4,task:'Найти в отрывках все тропы этого урока (эпитет, сравнение, гипербола, литота) и олицетворения. Записать каждый троп, назвать и сказать, какую роль он играет.',
  body:'1. Уж небо осенью дышало, / Уж реже солнышко блистало, / Короче становился день, / Лесов таинственная сень / С печальным шумом обнажалась, / Ложился на поля туман, / Гусей крикливых караван / Тянулся к югу: приближалась / Довольно скучная пора; / Стоял ноябрь уж у двора. (А. С. Пушкин, «Евгений Онегин») 2. Гонимы вешними лучами, / С окрестных гор уже снега / Сбежали мутными ручьями / На потопленные луга. / Улыбкой ясною природа / Сквозь сон встречает утро года. (А. С. Пушкин, «Евгений Онегин»)',
  key:'1. «Небо дышало» — олицетворение; «таинственная (сень)», «печальный (шум)», «крикливых (гусей)», «скучная (пора)» — эпитеты; «стоял ноябрь у двора» — олицетворение; в целом — картина печальной, затихающей осени. 2. «Вешние лучи гонят снега» — олицетворение; «мутными (ручьями)» — эпитет; «на потопленные луга» — эпитет-причастие; «улыбкой ясною природа встречает утро года» — олицетворение; настроение радостное, пробуждение.'},
 {n:39,l:3,st:4,task:'Сравнить научное и художественное описание снега. Выписать из художественного текста тропы, а из научного — слова, которые заменяют образы точными терминами. Объяснить различие задач.',
  body:'Научное: Снег — твёрдые атмосферные осадки в виде ледяных кристаллов, чаще всего шестилучевых. Плотность свежевыпавшего снега составляет 50–100 кг на кубический метр.<br>Художественное: Снег загорелся широким серебряным полем и весь обсыпался хрустальными звёздами. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки»)',
  key:'Научный текст: термины («твёрдые атмосферные осадки», «кристаллы», «плотность») и числа; образов нет; задача — сообщить знания. Художественный текст: «серебряное (поле)» — эпитет и метафора; «загорелся» — олицетворение или метафора; «обсыпался хрустальными звёздами» — метафора (снежинки — звёзды из хрусталя); задача — создать образ сверкающего снега и вызвать чувство. Различие: наука называет и измеряет, литература показывает и вызывает чувство.'},
 {n:40,l:3,st:4,task:'Определить в каждом отрывке главный троп из списка: эпитет, сравнение, гипербола, литота. Одно предложение может содержать несколько тропов — выписать все.',
  body:'1. Славная осень! Здоровый, ядрёный / Воздух усталые силы бодрит; / Лёд неокрепший на речке студёной / Словно как тающий сахар лежит. (Н. А. Некрасов, «Железная дорога») 2. Не ветер бушует над бором, / Не с гор побежали ручьи, / Мороз-воевода дозором / Обходит владенья свои. (Н. А. Некрасов, «Мороз, Красный нос») 3. А волны моря с печальным рёвом о камень бились... (М. Горький, «Песня о Соколе») 4. Отговорила роща золотая / Берёзовым, весёлым языком, / И журавли, печально пролетая, / Уж не жалеют больше ни о ком. (С. А. Есенин, «Отговорила роща золотая…») 5. Чичиков всё ещё стоял неподвижно на одном и том же месте, как человек, который весело вышел на улицу с тем, чтобы прогуляться, с глазами, расположенными глядеть на всё, и вдруг неподвижно остановился, вспомнив, что он позабыл что-то… (Н. В. Гоголь, «Мёртвые души»)',
  key:'1. «Словно как тающий сахар» — сравнение; «здоровый, ядрёный (воздух)», «неокрепший (лёд)», «студёной (речке)» — эпитеты. 2. «Мороз-воевода» — эпитет-приложение (и метафора); глаголы «бушует», «обходит» — олицетворение. 3. «Печальным (рёвом)» — эпитет, олицетворение. 4. «Золотая (роща)», «берёзовым, весёлым (языком)» — метафорические эпитеты; «отговорила» — олицетворение. 5. Развёрнутое сравнение «как человек, который весело вышел на улицу… и вдруг остановился»; «беззаботное выражение слетает с лица» — метафора.'},
 {n:41,l:3,st:5,os:'сочинение',task:'Написать описание грозы или тумана (5–7 предложений). Использовать два эпитета (образных), простое сравнение, одну гиперболу и одну литоту. Подчеркнуть их разными линиями и подписать.',
  key:'Проверить: 5–7 предложений; два настоящих эпитета (образных, а не «зимний», «деревянный»); сравнение с «как», «словно», «подобный» или творительным падежом; гипербола (преувеличение, которое явно не следует понимать буквально); литота (преуменьшение или «не без»). Образец: Туман лёг на луг мохнатым зверем. Дома тонули в молочной реке. Казалось, до соседней калитки целый день пути. Ни звука, ни шороха — только капля, как тихий колокольчик. Лишь дальний лай не без труда пробивался сквозь белую вату. Эпитеты: мохнатым, белую; сравнение: «как тихий колокольчик»; гипербола: «целый день пути»; литота: «не без труда».'},
 {n:42,l:3,st:5,task:'Задание для абитуриентов. Прочитать отрывок. Указать номера верных утверждений.',
  body:'Отрывок: Оно пылало так ярко, как солнце, и ярче солнца, и весь лес замолчал, освещённый этим факелом великой любви к людям, а тьма разлетелась от света его и там, глубоко в лесу, дрожащая, пала в гнилой зев болота. (М. Горький, «Старуха Изергиль»)<br>Утверждения: 1) В отрывке есть сравнение, выраженное союзом «как». 2) «Ярче солнца» — гипербола, выраженная сравнительной степенью. 3) «Весь лес замолчал» — олицетворение. 4) «Факел великой любви» — метафора. 5) «Гнилой (зев болота)» — эпитет. 6) В отрывке есть литота.',
  key:'Верные утверждения: 1, 2, 3, 4, 5. Пояснения: 6 — неверно: преуменьшения в отрывке нет, все образы направлены на усиление; 3 — верно: лес «замолчал» от изумления, как человек; 4 — верно: сердце Данко — факел, потому что освещает путь (метафора и аллегория).'},
// ── Урок 4. Синтаксические фигуры
 {n:43,l:4,st:1,task:'Определить, где повтор: в начале (анафора), в конце (эпифора) или внутри фразы (лексический повтор). Записать повторяющееся слово.',
  obr:'«Я слушаю дождь. Я слушаю сад. Я слушаю грозу»: начало, «я слушаю» — анафора.',
  body:'1. Мы шли и шли, и не было конца дороге. 2. Он ждал писем. Она ждала писем. Все ждали писем. 3. Гроза пришла. Гроза умыла двор. Гроза постучала в окна. 4. Весна пришла, весна, весна! 5. Светло в саду. Светло у ручья. Светло везде. 6. Горе мне, горе, горе!',
  key:'1. шли и шли — лексический повтор внутри фразы. 2. «ждал(а) писем» — эпифора (конец). 3. «Гроза» — анафора (начало). 4. «весна» — лексический повтор. 5. «Светло» — анафора. 6. «Горе» — лексический повтор.'},
 {n:44,l:4,st:2,task:'Найти в отрывках повторы. Записать, что повторяется, где стоит повтор и какая это фигура. Сказать, что повтор даёт.',
  obr:'«Люблю тебя, Петра творенье, / Люблю твой строгий, стройный вид»: «Люблю» в начале строк — анафора; чувство растёт.',
  body:'1. Пока свободою горим, / Пока сердца для чести живы, / Мой друг, отчизне посвятим / Души прекрасные порывы! (А. С. Пушкин, «К Чаадаеву») 2. Ты и убогая, / Ты и обильная, / Ты и могучая, / Ты и бессильная, / Матушка-Русь! (Н. А. Некрасов, «Кому на Руси жить хорошо») 3. Ветер, ветер! Ты могуч, / Ты гоняешь стаи туч, / Ты волнуешь сине море, / Всюду веешь на просторе, / Не боишься никого, / Кроме бога одного. (А. С. Пушкин, «Сказка о мёртвой царевне и о семи богатырях») 4. Все ждали вестей, все искали вестей: ночью, рано утром, в полдень — везде и всегда одни вести.',
  key:'1. «Пока» в начале строк — анафора: напор и единство. 2. «Ты и» в начале каждой строки — анафора (с параллелизмом): перечень противоположных черт, напор. 3. «Ты» в начале строк 2, 3 — анафора: обращение к ветру как к живому. 4. «Вестей» в конце частей — эпифора: подчёркивает главное слово.'},
 {n:45,l:4,st:2,task:'Определить: многосоюзие или бессоюзие. Объяснить, как это влияет на темп речи.',
  obr:'«Пришёл, увидел, победил»: бессоюзие — быстрый темп.',
  body:'1. И вдруг всё ожило: и леса, и пруды, и степи. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 2. Ему было и стыдно, и страшно, и тошно. (А. П. Чехов, «Беда») 3. …перед глазами ходил океан и колыхался, и гремел, и сверкал, и угасал, и светился, и уходил куда-то в бесконечность… (В. Г. Короленко, «Без языка») 4. Горят костры, звенят кузнечики, шумит камыш. 5. И пели птицы, и шумели деревья, и ручей шептал свою песню. 6. Хлопнула дверь, зазвенел звонок, затопали шаги.',
  key:'1. Многосоюзие («и леса, и пруды, и степи»): всё живое названо отдельно, речь замедляется. 2. Многосоюзие («и стыдно, и страшно, и тошно»): чувства нанизаны. 3. Многосоюзие («ходил океан и колыхался, и гремел, и сверкал…»): бесконечное движение. 4. Бессоюзие: быстрая смена картин. 5. Многосоюзие: размеренность, спокойствие. 6. Бессоюзие: быстрая последовательность событий.'},
 {n:46,l:4,st:2,task:'Найти эллипсис (пропуск члена предложения, ясный из контекста). Восстановить пропущенные слова и записать полные предложения.',
  obr:'«Он — в департамент, она — на рынок» → Он шёл в департамент, она шла на рынок.',
  body:'1. Мамонта — на погост, улана — на Кавказ, — вот те и вся недолга! (М. Горький, «В людях») 2. Она уложила их, как малых детей, одного — на полу, другого — на койке, и, когда они захрапели, вышла в сени. (М. Горький, «В людях») 3. Они выходили из квартиры только по нужде: он — в департамент, она — на рынок, и забыли даже о возможности каких-либо других отлучек. (М. Е. Салтыков-Щедрин, «Господа ташкентцы») 4. Были тут двери: одна — в детскую, другая — в гостиную. (А. П. Чехов, «Учитель словесности») 5. Прибыли из-за моря три князя: Рюрик — в Новгород, Синеус — в Ладогу, Трувор — в Изборск. (М. Е. Салтыков-Щедрин, «Современная идиллия») 6. Крутая радуга — к вёдру; пологая — к дождю. (Н. А. Некрасов, «Кому на Руси жить хорошо»)',
  key:'1. Мамонта — отправили на погост, улана — на Кавказ. 2. Одного — на полу, другого — на койке (уложила). 3. Он — идёт (шёл) в департамент, она — идёт (шла) на рынок. 4. Одна — вела в детскую, другая — в гостиную. 5. Рюрик — (сел) в Новгород, Синеус — (сел) в Ладогу, Трувор — (сел) в Изборск. 6. Крутая радуга — (предвещает) вёдро; пологая — (предвещает) дождь. Эллипсис делает фразу краткой, быстрой.'},
 {n:47,l:4,st:3,task:'Различить эллипсис и умолчание. В каждом примере определить, пропущено ли слово (эллипсис) или не доведена до конца мысль (умолчание). Объяснить.',
  obr:'«Мы — в лес, они — на луг»: эллипсис (пропущено «пошли»). «Я хотел сказать… но…»: умолчание (мысль оборвана).',
  body:'1. Мы — в лес, они — на луг. 2. Я хотел сказать... но, впрочем, нет... 3. Сын — в школу, отец — на завод, мать — в магазин, а бабушка — на скамейку у подъезда. 4. А если он вдруг... Нет, лучше не думать об этом. 5. Книги — на полку. 6. Один — за веслом, другой — за снастями.',
  key:'1. Эллипсис: пропущены глаголы («пошли», «пошли»). 2. Умолчание: мысль не договорена. 3. Эллипсис: пропущены глаголы. 4. Умолчание: «А если он вдруг...» — оборвано. 5. Эллипсис: пропущены глаголы («положи», «убери»). 6. Эллипсис: пропущены глаголы («потянулся», «потянулся»).'},
 {n:48,l:4,st:3,task:'Найти инверсию. Восстановить прямой порядок слов, записать и сказать, какое слово выделено в оригинале.',
  obr:'«Белеет парус одинокой» → Одинокой парус белеет. Выделено сказуемое «белеет».',
  body:'1. Выхожу один я на дорогу; / Сквозь туман кремнистый путь блестит; / Ночь тиха. Пустыня внемлет богу, / И звезда с звездою говорит. (М. Ю. Лермонтов, «Выхожу один я на дорогу…») 2. Однажды, в студёную зимнюю пору / Я из лесу вышел; был сильный мороз. / Гляжу, поднимается медленно в гору / Лошадка, везущая хворосту воз. (Н. А. Некрасов, «Крестьянские дети») 3. Зима!.. Крестьянин, торжествуя, / На дровнях обновляет путь; / Его лошадка, снег почуя, / Плетётся рысью как-нибудь; / Бразды пушистые взрывая, / Летит кибитка удалая… (А. С. Пушкин, «Евгений Онегин») 4. На краю деревни стоял старый дом. 5. Тихо шумел в вышине лес.',
  key:'1. Я выхожу один на дорогу; кремнистый путь блестит сквозь туман. Выделено: «выхожу» (действие) и «один». 2. Гляжу: медленно поднимается в гору лошадка (с воза хворосту). Выделены «медленно», «лошадка». 3. «Бразды пушистые взрывая» — взрывая пушистые бразды; выделено определение. 4. Прямой порядок: Старый дом стоял на краю деревни; в оригинале выделено место. 5. Прямой порядок: В вышине тихо шумел лес; выделен звук.'},
 {n:49,l:4,st:3,task:'Определить фигуру: параллелизм, антитеза или то и другое вместе. Записать, какие части фразы построены одинаково и что чему противопоставлено.',
  obr:'«Слуга царю, отец солдатам» — параллелизм: «слуга + царю», «отец + солдатам».',
  body:'1. Полковник наш рождён был хватом: / Слуга царю, отец солдатам… (М. Ю. Лермонтов, «Бородино») 2. Туча по небу идёт, / Бочка по морю плывёт. (А. С. Пушкин, «Сказка о царе Салтане») 3. Ты и убогая, / Ты и обильная, / Ты и могучая, / Ты и бессильная, / Матушка-Русь! (Н. А. Некрасов, «Кому на Руси жить хорошо») 4. Дети играли в саду, взрослые работали в поле. 5. Умный молчит, глупый кричит. (народная пословица) 6. Ученье — свет, а неученье — тьма. (народная пословица)',
  key:'1. Параллелизм (слуга царю — отец солдатам). 2. Параллелизм (туча по небу идёт — бочка по морю плывёт). 3. Параллелизм и антитеза («убогая — обильная», «могучая — бессильная»). 4. Параллелизм и сопоставление (дети — взрослые, сад — поле). 5. Параллелизм и антитеза (умный — глупый, молчит — кричит). 6. Параллелизм и антитеза (свет — тьма).'},
 {n:50,l:4,st:3,task:'Определить риторический вопрос, риторическое восклицание или риторическое обращение. Объяснить, что выражает автор.',
  obr:'«Свет наш солнышко!» — риторическое обращение к солнцу.',
  body:'1. Русь, куда ж несёшься ты, дай ответ? (Н. В. Гоголь, «Мёртвые души») 2. Не так ли и ты, Русь, что бойкая необгонимая тройка несёшься? (Н. В. Гоголь, «Мёртвые души») 3. Скажи-ка, дядя, ведь не даром / Москва, спалённая пожаром, / Французу отдана? (М. Ю. Лермонтов, «Бородино») 4. Знаете ли вы украинскую ночь? (Н. В. Гоголь, «Майская ночь») 5. «Свет наш солнышко! Ты ходишь / Круглый год по небу, сводишь / Зиму с тёплою весной, / Всех нас видишь под собой. (А. С. Пушкин, «Сказка о мёртвой царевне и о семи богатырях») 6. Как прекрасен этот мир!',
  key:'1. Риторическое обращение («Русь») и вопрос. 2. Риторический вопрос; обращение «Русь». 3. Риторический вопрос: ответ известен. 4. Риторический вопрос: привлечение внимания. 5. Риторическое обращение к солнцу. 6. Риторическое восклицание: восхищение.'},
 {n:51,l:4,st:4,task:'Определить период. Выписать повышение (ряд однотипных частей) и понижение (главная мысль). Составить схему: сколько частей в повышении и как они связаны. Сказать, что даёт период.',
  body:'1. Как ни старались люди, собравшись в одно небольшое место несколько сот тысяч, изуродовать ту землю, на которой они жались, как ни забивали камнями землю, чтобы ничего не росло на ней, как ни счищали всякую пробивающуюся травку, как ни дымили каменным углем и нефтью, как ни обрезывали деревья и ни выгоняли всех животных и птиц, — весна была весною даже и в городе. (Л. Н. Толстой, «Воскресение») 2. Если мы любим свою землю, если помним деда, который пахал это поле, если знаем, что река кормила наших предков, — значит, мы не можем равнодушно смотреть, как её губят.',
  key:'1. Повышение: пять частей с повторяющимися «как ни…» («как ни старались…», «как ни забивали…», «как ни счищали…», «как ни дымили…», «как ни обрезывали…») — перечисление усилий людей испортить землю; после паузы — понижение: «весна была весною даже и в городе». Период создаёт напряжение, затем вывод: природа сильнее. 2. Повышение: три части «если…, если…, если…»; понижение: «значит, мы не можем…». Роль: убедить, нагнетая условия.'},
 {n:52,l:4,st:4,task:'Определить все фигуры в отрывке и сказать, какую роль они играют в целом.',
  body:'Ветер, ветер! Ты могуч, / Ты гоняешь стаи туч, / Ты волнуешь сине море, / Всюду веешь на просторе, / Не боишься никого, / Кроме бога одного. (А. С. Пушкин, «Сказка о мёртвой царевне и о семи богатырях»)',
  key:'Риторическое обращение и восклицание («Ветер, ветер!»); анафора («Ты» в начале строк 2 и 3); параллелизм (однотипные строки о том, что делает ветер); олицетворение (ветер могуч, не боится никого, кроме бога). Роль: просьба о помощи обращена к ветру как к могучему живому существу, ритм напевный, как заклинание; перечисление подвигов ветра усиливает надежду героя.'},
 {n:53,l:4,st:4,task:'Для каждой фигуры придумать пример и подчеркнуть ключевое слово. Затем сделать в каждом примере замену на нейтральный вариант и сказать, что потеряно.',
  body:'Фигуры: анафора, эпифора, многосоюзие, бессоюзие, эллипсис, умолчание, инверсия, параллелизм.',
  key:'Образцы: анафора — Я слушал дождь. Я слушал ветер. Я слушал тишину. Эпифора — Он ушёл без шапки. Он вернулся без шапки. Он лёг спать без шапки. Многосоюзие — И шумел лес, и пела степь, и смеялись дети. Бессоюзие — Лес шумел, река пела, дети смеялись. Эллипсис — Отец — на завод, мать — в школу. Умолчание — Я думал... нет, лучше не скажу. Инверсия — Тихо шумел в вышине лес. Параллелизм — Лес кормит зверя, лес поит реку. Замена нейтральным убирает ритм и напор: анафора и эпифора теряют силу, умолчание — волнение, эллипсис — быстроту.'},
 {n:54,l:4,st:4,task:'Найти ошибки в рассуждениях ученика о фигурах. Для каждого утверждения записать, верно ли оно, и исправить.',
  body:'1. «В строке „Светло, светло, светло“ есть анафора». 2. «Бессоюзие замедляет речь». 3. «Эллипсис — это когда мысль не договорена». 4. «Период состоит из двух частей — повышения и понижения». 5. «Любой обратный порядок слов — инверсия». 6. «Эпифора — повтор слов в начале строк».',
  key:'1. Неверно: это лексический повтор (внутри одной фразы), анафора — повтор в начале соседних строк или фраз. 2. Неверно: бессоюзие ускоряет речь, замедляет многосоюзие. 3. Неверно: это умолчание; эллипсис — пропуск члена предложения. 4. Верно. 5. Неверно: инверсия есть только тогда, когда слово выделено ради выразительности. 6. Неверно: эпифора — повтор в конце.'},
 {n:55,l:4,st:5,os:'сочинение',task:'Написать текст «Дорога домой» (6–8 предложений). Использовать анафору, многосоюзие, эллипсис и один риторический вопрос. Выписать каждый приём и подписать.',
  key:'Проверить: 6–8 предложений; анафора (повтор начала соседних фраз); многосоюзие (не менее трёх «и» подряд); эллипсис (пропущен глагол, стоит тире); риторический вопрос. Образец: Дорога вела через лес. Дорога вела через луг. Дорога вела домой. И шумели сосны, и пели птицы, и тянулся дым над деревней. Отец — вперёд, я — следом, собака — рядом. Кто не знает, как сладко возвращаться домой? Приёмы: анафора («Дорога вела»), многосоюзие («и шумели, и пели, и тянулся»), эллипсис («отец — вперёд»), риторический вопрос.'},
 {n:56,l:4,st:5,task:'Задание для абитуриентов. Прочитать отрывок. Указать номера верных утверждений.',
  body:'Отрывок: Русь, куда ж несёшься ты, дай ответ? (Н. В. Гоголь, «Мёртвые души») Не так ли и ты, Русь, что бойкая необгонимая тройка несёшься? (Н. В. Гоголь, «Мёртвые души»)<br>Утверждения: 1) Первое предложение содержит риторическое обращение. 2) Оба предложения — риторические вопросы. 3) Во втором предложении есть сравнение. 4) «Бойкая необгонимая» — эпитеты. 5) Слово «Русь» повторено: это анафора. 6) В отрывке есть эллипсис.',
  key:'Верные утверждения: 1, 2, 3, 4. Пояснения: 5 — неверно: слово «Русь» стоит не в начале соседних строк, а внутри предложений — это лексический повтор; 6 — неверно: все члены предложений на месте; 3 — верно: «что бойкая необгонимая тройка» — сравнение с тройкой.'},
// ── Урок 5. Роль средства в тексте
 {n:57,l:5,st:1,task:'Соединить каждый приём с ролью, которую он чаще всего играет в тексте. Записать пары.',
  obr:'Бессоюзие — ускоряет речь.',
  body:'Приёмы: бессоюзие, многосоюзие, гипербола, олицетворение, антитеза, сравнение, звукоподражание, умолчание, риторическое обращение.<br>Роли: а) делает картину зримой через знакомое; б) показывает контраст; в) оживляет неживое; г) замедляет речь и выделяет каждое звено; д) передаёт недосказанность, волнение; е) ускоряет речь; ж) даёт услышать звук; з) выражает сильное чувство, зовёт к «собеседнику»; и) усиливает впечатление, создаёт комизм.',
  key:'Бессоюзие — е; многосоюзие — г; гипербола — и; олицетворение — в; антитеза — б; сравнение — а; звукоподражание — ж; умолчание — д; риторическое обращение — з.'},
 {n:58,l:5,st:2,task:'В каждой паре сравнить авторский вариант с нейтральным. Записать, что потеряно в нейтральном варианте.',
  obr:'«Зима поёт» — «зима шумит»: потеряна живость, зима больше не живое существо.',
  body:'1. а) Море дремлет и дышит опаловым туманом… (М. Горький, «Сказки об Италии») б) Залив спокойный, над ним туман. 2. а) Вот охватывает ветер стаи волн объятьем крепким и бросает их с размаху в дикой злобе на утёсы, разбивая в пыль и брызги изумрудные громады. (М. Горький, «Песня о Буревестнике») б) Дул сильный порыв, и волны разбивались о скалы. 3. а) Точно в действительности слышно, как и море стонет и в нём челночок поглощённый бьётся. (Н. С. Лесков, «Очарованный странник») б) Слышно, как шумит прибой и бьётся лодка. 4. а) Уже я с трудом различал отдалённые предметы; поле неясно белело вокруг; за ним, с каждым мгновением надвигаясь, громадными клубами вздымался угрюмый мрак. (И. С. Тургенев, «Бежин луг») б) Было уже темно, видно было плохо.',
  key:'1. Потеряно олицетворение: море «дремлет и дышит» — живое, спокойное. 2. Потеряно олицетворение: ветер «охватывает объятьем» и «бросает в злобе» — живая сила, борьба. 3. Потеряны олицетворение «море стонет» и сравнение «точно в действительности»: пропал стон волны. 4. Потеряны эпитет «угрюмый» и метафора «громадными клубами мрак»: мрак перестал быть живой силой.'},
 {n:59,l:5,st:2,task:'Для каждой фразы выбрать из списка роль приёма и записать название приёма.',
  obr:'«Он над тучами смеётся» — олицетворение; оживляет Буревестника.',
  body:'Роли: оживляет; усиливает впечатление; ускоряет; замедляет; показывает контраст; делает зримым; выражает насмешку.<br>1. Он над тучами смеётся, он от радости рыдает! (М. Горький, «Песня о Буревестнике») 2. Дорога длинная-длинная. 3. Шумел лес, пела степь, кричали птицы, бежали звери, дрожала земля. 4. И шумели деревья, и пели птицы, и звенел ручей. 5. Небо — бездна, а я — песчинка. 6. Спасибо, что напомнил: теперь я точно опоздаю на самый важный в году урок!',
  key:'1. Олицетворение (смеётся, рыдает) — оживляет. 2. Сравнение — делает зримым (и гипербола «длинная-длинная» — усиливает). 3. Бессоюзие — ускоряет. 4. Многосоюзие — замедляет. 5. Антитеза — показывает контраст. 6. Ирония — выражает насмешку.'},
 {n:60,l:5,st:3,task:'Сформулировать роль средства по шаблону: «средство + что делает + зачем». Выписать из каждого отрывка по одному выразительному слову или обороту.',
  obr:'«Он над тучами смеётся» — олицетворение: показывает Буревестника радостным, и читатель разделяет его радость.',
  body:'1. Синим пламенем пылают стаи туч над бездной моря. (М. Горький, «Песня о Буревестнике») 2. Море ловит стрелы молний и в своей пучине гасит. (М. Горький, «Песня о Буревестнике») 3. Точно огненные змеи, вьются в море, исчезая, отраженья этих молний. (М. Горький, «Песня о Буревестнике») 4. Чайки стонут перед бурей, — стонут, мечутся над морем и на дно его готовы спрятать ужас свой пред бурей. (М. Горький, «Песня о Буревестнике») 5. Глухо отдавались мои шаги в застывающем воздухе. (И. С. Тургенев, «Бежин луг»)',
  key:'Примерные формулировки. 1. «Синим пламенем пылают стаи туч» — метафора: тучи как огонь; передаёт грозу и красоту опасности. 2. «Море ловит стрелы молний и гасит» — олицетворение: море как могучий воин. 3. «Точно огненные змеи вьются отраженья молний» — сравнение: зримо показывает извивающиеся молнии. 4. «Чайки стонут» — олицетворение и повтор «стонут»: страх птиц перед бурей. 5. «Глухо отдавались шаги» — звукопись [г], [д], [х] и эпитет «глухо»: передают тишину ночи и одинокий шаг.'},
 {n:61,l:5,st:3,task:'В каждом задании выбрать верный анализ роли средства. Объяснить, почему остальные записи неверны.',
  obr:'«Зима поёт»: верна запись, где названы средство и его действие («олицетворение… поэтому зима кажется живой»); запись «красиво» ничего не объясняет.',
  body:'1. «Зима поёт, аукает» (Есенин). а) Метафора, потому что красиво. б) Олицетворение: зима ведёт себя как человек, поэтому она кажется живой и доброй. в) Сравнение, потому что есть слово «зима». 2. «Мужичок с ноготок» (Некрасов). а) Гипербола: мужичок очень большой. б) Литота: мужичок очень маленький, и образ получается ласковым. в) Антитеза: мужичок противопоставлен ногтю. 3. «Швед, русский — колет, рубит, режет» (Пушкин). а) Бессоюзие: ускоряет речь, показывает быстрый бой. б) Многосоюзие: замедляет речь. в) Эллипсис: не хватает подлежащего.',
  key:'1. б. (а — ярлык «красиво» не объясняет; в — сравнения нет). 2. б. (а — «с ноготок» значит очень маленький; в — нет противопоставления). 3. а. (б — союзов нет, а не повторяются; в — подлежащие названы: швед, русский).'},
 {n:62,l:5,st:3,task:'Определить роль звукописи и повтора слов в строках. Сказать, чем звукопись отличается от лексического повтора по роли.',
  obr:'«Горе, горе!»: лексический повтор — усиливает чувство; горе сильнее.',
  body:'1. Чёрный вечер. / Белый снег. / Ветер, ветер! / На ногах не стоит человек. (А. А. Блок, «Двенадцать») 2. Земля тряслась — как наши груди; / Смешались в кучу кони, люди, / И залпы тысячи орудий / Слились в протяжный вой… (М. Ю. Лермонтов, «Бородино») 3. Море шепталось по-прежнему с берегом, и ветер всё так же носил его шёпот по степи. (М. Горький, «Макар Чудра») 4. Девушка пела в церковном хоре / О всех усталых в чужом краю, / О всех кораблях, ушедших в море, / О всех, забывших радость свою. (А. А. Блок, «Девушка пела в церковном хоре»)',
  key:'1. Лексический повтор «ветер» — усиление; ветер заполняет всё. 2. Гласные [ы], [и], [у] («тысячи орудий слились в протяжный вой») тянутся, как вой: звук передаёт гул боя; сравнение «как наши груди» показывает силу удара. 3. [ш], [п], [с] — звукопись: шёпот волн, шорох. 4. [о], [у] и повтор «о всех» — протяжный напев, печаль. Звукопись изображает звук; лексический повтор усиливает мысль и чувство.'},
 {n:63,l:5,st:3,task:'Сравнить роль двух средств в отрывках и объяснить, чем они отличаются.',
  obr:'«Как стекло» (лёд) и «как струны» (провода): оба сравнения, но первое показывает хрупкость, второе — звучание.',
  body:'1. а) На другой день переехали мы по гладкому, как зеркало, льду страшную для меня Волгу. (С. Т. Аксаков, «Детские годы Багрова-внука») б) А в ясную даль убегают чётко видные телеграфные столбы, и проволоки их, как серебряные струны, скользят по склону ясного неба. (И. А. Бунин, «Антоновские яблоки») 2. а) Гонимы вешними лучами, / С окрестных гор уже снега / Сбежали мутными ручьями / На потопленные луга. / Улыбкой ясною природа / Сквозь сон встречает утро года. (А. С. Пушкин, «Евгений Онегин») б) Под голубыми небесами / Великолепными коврами, / Блестя на солнце, снег лежит; / Прозрачный лес один чернеет, / И ель сквозь иней зеленеет, / И речка подо льдом блестит. (А. С. Пушкин, «Зимнее утро»)',
  key:'1. (а) «гладкому, как зеркало, льду»: сравнение показывает идеальную гладкость льда; (б) «как серебряные струны»: сравнение превращает провода в музыкальный инструмент и делает картину звучащей. 2. (а) «Улыбкой ясною природа встречает утро года»: олицетворение — радость весны; (б) «Под голубыми небесами / Великолепными коврами»: сравнение (ковры) и эпитеты — красота и праздничность зимы.'},
 {n:64,l:5,st:4,task:'Разобрать две строфы Лермонтова. 1) Для каждой записать главное средство. 2) Сказать, какую роль оно играет. 3) Объяснить, как строфы связаны по смыслу.',
  body:'Играют волны — ветер свищет, / И мачта гнётся и скрыпит... / Увы! Он счастия не ищет / И не от счастия бежит! (М. Ю. Лермонтов, «Парус»)<br>Под ним струя светлей лазури, / Над ним луч солнца золотой... / А он, мятежный, просит бури, / Как будто в бурях есть покой! (М. Ю. Лермонтов, «Парус»)',
  key:'2-я строфа: звукопись [в], [с], [и] («ветер свищет», «мачта гнётся и скрыпит») и олицетворение «он счастия не ищет» — парус как человек; параллелизм/антитеза «не ищет — не бежит» — беспокойство. 3-я строфа: антитеза (спокойное небо и просьба о буре), эпитеты («светлей», «золотой», «мятежный»), сравнение «светлей лазури», риторическое восклицание — парус сознательно просит бури. Смысл: от тревоги — к выбору борьбы.'},
 {n:65,l:5,st:4,task:'Найти ошибки в употреблении выразительных средств. Объяснить, что неверно, и исправить.',
  body:'1. В инструкции: «Шкаф — сердце комнаты». 2. «Современный пароход науки стоит на трёх китах, а над его мачтами парит орёл новых идей и плывёт по волнам тумана». 3. «Он ловил каждое слово, а потом море эмоций вышло из берегов». 4. «Тёплое солнце смеялось над ледяной улыбкой зимы, стучавшей в окно клювом». 5. «Ручей впадает в озеро».',
  key:'1. Образность в инструкции неуместна: нужен точный язык. 2. Смешение образов: пароход и киты. 3. Штамп «море эмоций» и неудачный образ. 4. Смешение образов: солнце смеётся, зима улыбается ледяной улыбкой, стучит клювом — слишком много несовместимых образов. 5. Неудачное сравнение: смысл не передаёт реальный процесс, вызывает неуместный образ.'},
 {n:66,l:5,st:4,task:'Определить, в каком из текстов выразительное средство уместно, а в каком — лишнее. Объяснить свой выбор и переписать лишнее без образа.',
  body:'1. Заявление: «Прошу вас, как добрую фею, спасти мою душу от экзаменов, которые давят, как каменная плита». 2. Рассказ: «Туман лёг на деревню серой кошкой». 3. Инструкция: «Нить, как огонь, пройдёт сквозь ушко». 4. Научный текст: «Звёзды — далёкие миры, которые подмигивают нам с высоты». 5. Речь на митинге: «Наша площадь — живое сердце города, и мы не дадим ей опустеть!»',
  key:'1. Лишнее (деловой стиль): «Прошу освободить меня от экзаменов». 2. Уместно (художественный). 3. Лишнее: «Нить продевают в ушко иглы». 4. Лишнее (научный стиль): «Звёзды — удалённые небесные тела». 5. Уместно (публицистика): образ усиливает убеждение.'},
 {n:67,l:5,st:4,task:'Определить, какие метафоры стёртые (стали обычными названиями), а какие авторские. Для авторских сформулировать роль.',
  body:'1. ножка стула; 2. Стройные пальмы, латании и филодендроны отражаются в бесконечных зеркалах и, образуя океан зелени, уносят ваше воображение в страну (А. П. Чехов, «Идиллия»); 3. нос корабля; 4. Извергая клубы тяжёлого, серого дыма, пассажирский поезд, как огромное пресмыкающееся, исчезал в степной дали, в жёлтом море хлебов. (М. Горький, «Скуки ради»); 5. хвост самолёта; 6. Лес надел багряный кафтан осени.',
  key:'Стёртые: ножка стула, нос корабля, хвост самолёта. Авторские: 2 («океан зелени»: безбрежные заросли показаны как океан); 4 («море хлебов»: колышущиеся колосья как море); 6 («лес надел кафтан»: деревья в красных листьях, как в одежде). Роль авторских метафор — создать зрительный, эмоциональный образ.'},
 {n:68,l:5,st:4,task:'Определить роль средств в двух строфах Тютчева и объяснить, чем они различаются настроением.',
  body:'Гремят раскаты молодые! / Вот дождик брызнул, пыль летит, / Повисли перлы дождевые, / И солнце нити золотит. (Ф. И. Тютчев, «Весенняя гроза»)<br>С горы бежит поток проворный, / В лесу не молкнет птичий гам, / И гам лесной, и шум нагорный — / Всё вторит весело громам. (Ф. И. Тютчев, «Весенняя гроза»)',
  key:'Строфа 2: восклицание («Гремят раскаты молодые!») и эпитет «молодые» передают радость; метафоры «перлы дождевые», «нити» превращают дождь и солнце в драгоценности; олицетворение «солнце нити золотит» — свет как мастерство. Строфа 3: олицетворение «поток проворный», «всё вторит весело громам», многосоюзие «и гам лесной, и шум нагорный» — хор звуков природы. Настроение обеих строф радостное; вторая строфа добавляет общность: вся природа участвует в празднике.'},
 {n:69,l:5,st:5,os:'анализ текста',task:'Написать мини-анализ (6–8 предложений) строфы. Назвать 3–4 средства выразительности, объяснить роль каждого и сделать вывод об образе. Использовать формулу «средство — что делает — зачем».',
  body:'А по двору метелица / Ковром шёлковым стелется, / Но больно холодна. (С. А. Есенин, «Поёт зима — аукает…») Воробышки игривые, / Как детки сиротливые, / Прижались у окна. (С. А. Есенин, «Поёт зима — аукает…»)',
  key:'Проверить: названы не менее трёх средств; у каждого указана роль, а не «для красоты»; опора на слова текста; вывод. Образец: Метель названа «метелица» (уменьшительное) и «стелется ковром шёлковым» — сравнение показывает, как мягко и красиво укрыта земля. Слова «но больно холодна» меняют настроение: зима ласковая, но холодная. Воробышки, «как детки сиротливые, прижались у окна», — сравнение вызывает жалость. Так создан образ зимы, в котором красота соединена с холодом и жалостью.'},
 {n:70,l:5,st:5,task:'Задание для абитуриентов. Прочитать отрывок. Указать номера верных утверждений.',
  body:'Отрывок: Синим пламенем пылают стаи туч над бездной моря. (М. Горький, «Песня о Буревестнике») Море ловит стрелы молний и в своей пучине гасит. (М. Горький, «Песня о Буревестнике») Точно огненные змеи, вьются в море, исчезая, отраженья этих молний. (М. Горький, «Песня о Буревестнике»)<br>Утверждения: 1) «Синим пламенем пылают стаи туч» — метафора. 2) «Море ловит стрелы молний» — олицетворение. 3) «Точно огненные змеи» — сравнение. 4) Все три предложения усиливают картину грозы и красоты опасности. 5) В отрывке есть гипербола. 6) В отрывке нет ни одного эпитета.',
  key:'Верные утверждения: 1, 2, 3, 4. Пояснения: 5 — неверно: образы масштабные, но преувеличения как приёма нет; 6 — неверно: «синим (пламенем)», «огненные (змеи)» — эпитеты.'},
// ── Урок 6. Сводка и анализ отрывка
 {n:71,l:6,st:1,task:'Распределить средства по трём уровням: звуки, слова (тропы), построение фраз (фигуры).',
  obr:'Аллитерация — звуки.',
  body:'аллитерация, эпитет, анафора, метафора, ассонанс, эллипсис, гипербола, звукоподражание, антитеза, олицетворение, многосоюзие, ирония, инверсия, сравнение, литота',
  key:'Звуки: аллитерация, ассонанс, звукоподражание. Тропы (слова): эпитет, метафора, гипербола, олицетворение, ирония, сравнение, литота. Фигуры (фразы): анафора, эллипсис, антитеза, многосоюзие, инверсия.'},
 {n:72,l:6,st:2,task:'Определить средство по определению. Записать название.',
  obr:'Повтор одинаковых гласных звуков — ассонанс.',
  body:'1. Образное определение. 2. Преувеличение. 3. Описательный оборот вместо названия. 4. Повтор конца соседних строк или фраз. 5. Пропуск члена предложения. 6. Мысль, не доведённая до конца. 7. Перенос названия по сходству. 8. Хвалят, имея в виду обратное. 9. Идея, показанная конкретным образом. 10. Слово, воспроизводящее звук.',
  key:'1. Эпитет. 2. Гипербола. 3. Перифраза. 4. Эпифора. 5. Эллипсис. 6. Умолчание. 7. Метафора. 8. Ирония. 9. Аллегория. 10. Звукоподражание.'},
 {n:73,l:6,st:2,task:'Определить средство выразительности в каждом примере и записать уровень (звуки, тропы, фигуры).',
  obr:'«Ку-ку» — звукоподражание (звуки); «рыжая осень» — метафорический эпитет (тропы).',
  body:'1. Были тут двери: одна — в детскую, другая — в гостиную. (А. П. Чехов, «Учитель словесности») 2. Шуршат шелковистые шторы, шепчутся шаги в коридоре. 3. Над городом повис купол тишины. 4. Ты хорошая, добрая, и ты не глупая, ты поймёшь... (А. П. Чехов, «Анюта») 5. Хлоп! — хлопнула дверь. 6. Тишина, тишина, тишина.',
  key:'1. Эллипсис (фигура). 2. Аллитерация [ш] (звуки). 3. Метафора «купол тишины» (троп). 4. Литота «не глупая» (троп). 5. Звукоподражание «хлоп» (звуки). 6. Лексический повтор (фигура).'},
 {n:74,l:6,st:3,task:'Разобрать строфу по плану: 1) тема и настроение; 2) звуки; 3) тропы; 4) фигуры; 5) роль вместе; 6) вывод.',
  obr:'Тема: зимний пейзаж; настроение: восхищение.',
  body:'Под голубыми небесами / Великолепными коврами, / Блестя на солнце, снег лежит; / Прозрачный лес один чернеет, / И ель сквозь иней зеленеет, / И речка подо льдом блестит. (А. С. Пушкин, «Зимнее утро»)',
  key:'1. Тема: зимний пейзаж; настроение: радостное восхищение. 2. Звуки: [л], [н], [с] — плавность («Блестя на солнце, снег лежит»). 3. Тропы: «голубыми (небесами)», «великолепными (коврами)» — эпитеты; «коврами» — творительный сравнения (снег — ковры); «прозрачный лес», «ель... зеленеет» — эпитеты и олицетворение. 4. Фигуры: многосоюзие «и ель… и речка» — перечисление; инверсия «Под голубыми небесами». 5. Все средства вместе создают яркую, празднично чистую картину. 6. Пушкин видит зиму как торжество красоты.'},
 {n:75,l:6,st:3,task:'Найти в предложениях Тургенева все средства выразительности и записать уровень каждого.',
  obr:'«Заря разливается кротким румянцем»: олицетворение и эпитет (тропы).',
  body:'1. С самого раннего утра небо ясно; утренняя заря не пылает пожаром: она разливается кротким румянцем. (И. С. Тургенев, «Бежин луг») 2. Подобно островам, разбросанным по бесконечно разлившейся реке, обтекающей их глубоко прозрачными рукавами ровной синевы, они почти не трогаются с места; далее, к небосклону, они сдвигаются, теснятся, синевы между ними уже не видать; но сами они так же лазурны, как небо: они все насквозь проникнуты светом и теплотой. (И. С. Тургенев, «Бежин луг»)',
  key:'1. «Утренняя заря не пылает пожаром: она разливается кротким румянцем» — метафора и антитеза (пожар — румянец), олицетворение (заря «разливается»); эпитет «кротким». 2. Развёрнутое сравнение «подобно островам, разбросанным по бесконечно разлившейся реке»; эпитеты «глубоко прозрачными», «ровной синевы», «лазурны»; сравнение «так же лазурны, как небо»; повторение «они» (параллелизм). Всё вместе рисует спокойное небо.'},
 {n:76,l:6,st:3,task:'Найти в отрывках сравнения. Для каждого записать: что с чем сравнивается и какую роль играет сравнение.',
  obr:'«Облака, как дым»: облака сравниваются с дымом — лёгкость, неопределённость.',
  body:'1. К вечеру эти облака исчезают; последние из них, черноватые и неопределённые, как дым… (И. С. Тургенев, «Бежин луг») 2. …на месте, где оно закатилось так же спокойно, как спокойно взошло на небо, алое сиянье стоит недолгое время над потемневшей землёй, и, тихо мигая, как бережно несомая свечка, затеплится на нём вечерняя звезда. (И. С. Тургенев, «Бежин луг») 3. Между тем ночь приближалась и росла, как грозовая туча; казалось, вместе с вечерними парами отовсюду поднималась и даже с вышины лилась темнота. (И. С. Тургенев, «Бежин луг»)',
  key:'1. Облака — дым (черноватые и неопределённые): лёгкость, расплывчатость. 2. Вечерняя звезда — бережно несомая свеча: хрупкость света. 3. Ночь — грозовая туча: надвигающаяся тьма, тревога. Сравнения делают картину зримой.'},
 {n:77,l:6,st:3,task:'Найти в стихотворных строках фигуры и тропы. Для каждой строки записать тип (звуки, троп, фигура) и роль.',
  obr:'«Печальная берёза»: эпитет (троп) — берёза кажется грустной.',
  body:'1. Печальная берёза / У моего окна, / И прихотью мороза / Разубрана она. (А. А. Фет, «Печальная берёза») 2. Однажды, в студёную зимнюю пору / Я из лесу вышел; был сильный мороз. / Гляжу, поднимается медленно в гору / Лошадка, везущая хворосту воз. (Н. А. Некрасов, «Крестьянские дети») 3. Есть женщины в русских селеньях / С спокойною важностью лиц, / С красивою силой в движеньях, / С походкой, со взглядом цариц. (Н. А. Некрасов, «Мороз, Красный нос») 4. Буря мглою небо кроет, / Вихри снежные крутя; / То, как зверь, она завоет, / То заплачет, как дитя. (А. С. Пушкин, «Зимний вечер»)',
  key:'1. Эпитет «печальная»; олицетворение; инверсия «разубрана она» — береза как грустная невеста. 2. Инверсия («Гляжу, поднимается медленно в гору Лошадка…»); эпитеты «студёную», «зимнюю»; медленный ритм — картина зимней дороги. 3. Параллелизм «С… важностью, С… силой, С… походкой»; эпитеты; сравнение «со взглядом цариц» — величавая женщина. 4. Сравнения «как зверь», «как дитя»; параллелизм «То… то»; звукоподражание «завоет» — буря как живое существо.'},
 {n:78,l:6,st:4,task:'Проанализировать прозаический отрывок по плану. Для каждого пункта привести примеры из текста.',
  body:'Уже я с трудом различал отдалённые предметы; поле неясно белело вокруг; за ним, с каждым мгновением надвигаясь, громадными клубами вздымался угрюмый мрак. (И. С. Тургенев, «Бежин луг») Глухо отдавались мои шаги в застывающем воздухе. (И. С. Тургенев, «Бежин луг») Между тем ночь приближалась и росла, как грозовая туча; казалось, вместе с вечерними парами отовсюду поднималась и даже с вышины лилась темнота. (И. С. Тургенев, «Бежин луг»)',
  key:'1. Тема: наступающая ночь в поле; настроение: тревога, одиночество. 2. Звуки: [г], [д], [х] в «глухо отдавались», «громадными клубами»; звуки «глухие», как шаги в тишине. 3. Тропы: «громадными клубами вздымался угрюмый мрак» — метафора и эпитет; «ночь росла, как грозовая туча» — сравнение; «побледневшее небо» — олицетворение; «звёздочки замелькали, зашевелились» — олицетворение. 4. Фигуры: многочленные предложения с перечислением и деепричастным оборотом — плавное нарастание. 5. Все средства сходятся: тьма наступает, как живая сила, а человек мал. 6. Тургенев передаёт состояние тревожного ожидания через картину природы.'},
 {n:79,l:6,st:4,task:'Проанализировать фрагмент Горького. Выписать по одному средству из трёх уровней и сказать, какую картину они создают вместе.',
  body:'Чайки стонут перед бурей, — стонут, мечутся над морем и на дно его готовы спрятать ужас свой пред бурей. (М. Горький, «Песня о Буревестнике») Это смелый Буревестник гордо реет между молний над ревущим гневно морем; то кричит пророк победы: — Пусть сильнее грянет буря!.. (М. Горький, «Песня о Буревестнике»)',
  key:'Звуки: повтор [с], [т] («стонут, мечутся, спрятать») — свист и стоны перед бурей. Тропы: олицетворение «чайки стонут»; эпитеты «смелый», «ревущим гневно»; метафора «пророк победы». Фигуры: многосоюзие/перечисление «стонут, мечутся… готовы»; восклицание «Пусть сильнее грянет буря!». Вместе: контраст страха чаек и смелости Буревестника создаёт образ человека, который ждёт борьбы.'},
 {n:80,l:6,st:4,task:'Сравнить олицетворение в стихах Лермонтова и в прозе Чехова. Выписать по два средства из каждого текста и сказать, чем различаются настроение и ритм.',
  body:'Лермонтов: Выхожу один я на дорогу; / Сквозь туман кремнистый путь блестит; / Ночь тиха. Пустыня внемлет богу, / И звезда с звездою говорит. (М. Ю. Лермонтов, «Выхожу один я на дорогу…»)<br>Чехов: Дождь хлестал меня по лицу, а ветер сердито трепал мои полы, шапку... (А. П. Чехов, «Драма на охоте»)',
  key:'Лермонтов: инверсия («Выхожу один я на дорогу»), олицетворение («пустыня внемлет богу», «звезда с звездою говорит»), эпитет «кремнистый (путь)», рифма; ритм мерный, настроение покоя и торжественности. Чехов: олицетворение («дождь хлестал», «ветер сердито трепал»), бессоюзие «шапку…»; ритм быстрый, настроение — досада и борьба с непогодой. Различие: в стихах олицетворение приводит к покою и тайне, в прозе — к живому, бытовому чувству.'},
 {n:81,l:6,st:4,task:'Найти недостатки в учебных анализах и исправить.',
  body:'1. «В отрывке есть эпитеты, метафоры и сравнения». 2. «Автор использует олицетворение, потому что это красиво и поэтому читателю понравится». 3. «Анафора показывает грусть» (о строке, где радость). 4. «„Седой“ — просто цвет». 5. «Звукопись — повтор слов».',
  key:'1. Нет конкретных примеров и ролей. 2. «Потому что красиво» — не роль; нужно сказать, что оживляется. 3. Роль не из текста: анафора усиливает радость. 4. «Седой» в «седой равнине моря» — метафорический эпитет: море старое, покрытое пеной. 5. Звукопись — повтор звуков, а не слов.'},
 {n:82,l:6,st:5,os:'анализ текста',task:'Написать анализ стихотворения Лермонтова «Тучи» (8–10 предложений) по плану урока.',
  body:'Тучки небесные, вечные странники! / Степью лазурною, цепью жемчужною / Мчитесь вы, будто как я же, изгнанники / С милого севера в сторону южную. (М. Ю. Лермонтов, «Тучи»)<br>Кто же вас гонит: судьбы ли решение? / Зависть ли тайная? злоба ль открытая? / Или на вас тяготит преступление? / Или друзей клевета ядовитая? (М. Ю. Лермонтов, «Тучи»)<br>Нет, вам наскучили нивы бесплодные... / Чужды вам страсти и чужды страдания; / Вечно холодные, вечно свободные, / Нет у вас родины, нет вам изгнания. (М. Ю. Лермонтов, «Тучи»)',
  key:'Проверить: тема (тучи-странники и изгнанник), настроение (грусть и восхищение свободой); звуки ([ч], [ж], [л] — плавный бег); тропы (эпитеты «небесные», «вечные», «лазурною», «жемчужною», «ядовитая»; олицетворение и метафора «изгнанники»); фигуры (обращение «Тучки небесные», риторические вопросы «Кто же вас гонит?», антитеза «изгнанники — нет вам изгнания»); роль вместе; вывод (тучи вызывают зависть к свободе). Каждое утверждение подтверждается словами текста.'},
 {n:83,l:6,st:5,task:'Задание для абитуриентов. Прочитать текст. Указать номера верных утверждений.',
  body:'Текст: С горы бежит поток проворный, / В лесу не молкнет птичий гам, / И гам лесной, и шум нагорный — / Всё вторит весело громам. (Ф. И. Тютчев, «Весенняя гроза»)<br>Утверждения: 1) «Проворный» — эпитет. 2) «И гам лесной, и шум нагорный» — многосоюзие. 3) «Всё вторит весело громам» — олицетворение. 4) В тексте есть гипербола. 5) В тексте есть риторический вопрос. 6) В тексте есть антитеза.',
  key:'Верные утверждения: 1, 2, 3. Пояснения: 4 — неверно: преувеличения как приёма нет; 5 — неверно: вопросительных предложений нет; 6 — неверно: противопоставления нет.'},
 {n:84,l:6,st:5,os:'сочинение',task:'Написать рассуждение «Зачем писателю тропы и фигуры» (8–10 предложений). Привести по одному примеру звукописи, тропа и фигуры и показать, что каждый даёт тексту.',
  key:'Проверить: тезис; три примера (звукопись, троп, фигура) из классики или своих текстов; к каждому названа роль; вывод. Образец: Выразительные средства помогают увидеть, услышать и почувствовать. Звукопись у Пушкина («Шипенье пенистых бокалов») даёт услышать шипение пены. Олицетворение «Поёт зима» оживляет природу. Анафора «Люблю тебя, Петра творенье» усиливает восхищение. Без таких средств текст стал бы просто сообщением.'},
// ── Повторение
 {n:85,l:7,st:2,task:'Определить средство выразительности в каждом примере (звукоподражание, аллитерация, эпитет, сравнение, метафора, олицетворение, гипербола, литота, антитеза, анафора, бессоюзие, многосоюзие).',
  obr:'«Багряная осень» — эпитет (метафорический); «Метель злится» — олицетворение.',
  body:'1. Ху-ху! — ухнула сова. 2. Багряная осень. 3. Мороз и тепло, камень и вода. 4. Дорога, как лента, вилась по лугу. 5. Мужичок с ноготок. 6. Миллион раз повторял! 7. Метель злится. 8. Ни дня без дела, ни дня без книги. 9. Пришёл, увидел, победил. 10. И шумят сады, и поют ручьи, и смеются дети.',
  key:'1. Звукоподражание. 2. Эпитет (метафорический). 3. Антитеза. 4. Сравнение. 5. Литота. 6. Гипербола. 7. Олицетворение. 8. Анафора («ни дня без…»). 9. Бессоюзие. 10. Многосоюзие.'},
 {n:86,l:7,st:3,task:'Определить средства в строфах и записать уровень (звуки, тропы, фигуры).',
  obr:'«Словно зеркало» — сравнение (тропы).',
  body:'1. Кругом с тоской глубокою / Плывут в страну далёкую / Седые облака. (С. А. Есенин, «Поёт зима — аукает…») 2. Ну ж был денёк! Сквозь дым летучий / Французы двинулись, как тучи, / И всё на наш редут. (М. Ю. Лермонтов, «Бородино») 3. Море ревёт в эти ночи, и деревья стонут от ветра, и кругом не горит ни одного огня… (А. И. Куприн, «Пустые дачи») 4. Бывало, если вечер тих, -- озеро покойно; на деревах, что по берегу росли, не шелохнёт, вода неподвижна, словно зеркало. (Ф. М. Достоевский, «Бедные люди»)',
  key:'1. Эпитеты «глубокою», «далёкую», «седые»; метафора «плывут облака»; инверсия. 2. Сравнение «как тучи» (французы — тучи); эпитет «летучий (дым)»; восклицание «Ну ж был денёк!». 3. Олицетворение «море ревёт», «деревья стонут»; многосоюзие «и… и». 4. Сравнение «словно зеркало» (вода неподвижна).'},
 {n:87,l:7,st:3,task:'Найти и назвать все средства (звукопись, тропы, фигуры) в предложениях.',
  obr:'«Солнце хмурилось» — олицетворение.',
  body:'1. Восходящее солнце хмурилось на уездный город, петухи ещё только потягивались… (А. П. Чехов, «Драма на охоте») 2. Море ревёт в эти ночи, и деревья стонут от ветра, и кругом не горит ни одного огня… (А. И. Куприн, «Пустые дачи») 3. Ветерок беспокойно содрогался в тёмных деревьях, и где-то далеко за небосклоном, словно про себя, ворчал гром сердито и глухо. (И. С. Тургенев, «Первая любовь») 4. Буря мглою небо кроет, / Вихри снежные крутя; / То, как зверь, она завоет, / То заплачет, как дитя. (А. С. Пушкин, «Зимний вечер»)',
  key:'1. «Солнце хмурилось» — олицетворение; эпитет «восходящее». 2. «Море ревёт», «деревья стонут» — олицетворение; многосоюзие «и… и». 3. «Ворчал гром», «ветерок содрогался» — олицетворение; сравнение «словно про себя». 4. «То, как зверь, она завоет, / То заплачет, как дитя» — сравнения, олицетворение (буря воет и плачет), параллелизм «то… то».'},
 {n:88,l:7,st:3,task:'Определить фигуры речи и записать, что повторяется или пропущено.',
  obr:'«Пока… пока…» — повтор в начале строк: анафора.',
  body:'1. Пока свободою горим, / Пока сердца для чести живы, / Мой друг, отчизне посвятим / Души прекрасные порывы! (А. С. Пушкин, «К Чаадаеву») 2. И вдруг всё ожило: и леса, и пруды, и степи. (Н. В. Гоголь, «Вечера на хуторе близ Диканьки») 3. Они выходили из квартиры только по нужде: он — в департамент, она — на рынок, и забыли даже о возможности каких-либо других отлучек. (М. Е. Салтыков-Щедрин, «Господа ташкентцы») 4. …больше всего береги и копи копейку: эта вещь надёжнее всего на свете. (Н. В. Гоголь, «Мёртвые души»)',
  key:'1. Анафора («Пока» в начале строк), параллелизм. 2. Многосоюзие («и леса, и пруды, и степи»). 3. Эллипсис (пропущены сказуемые). 4. Синекдоха «копейка» вместо «деньги».'},
 {n:89,l:7,st:4,task:'Определить, о каком средстве идёт речь, если возможны два ответа, и обосновать выбор по контексту.',
  body:'1. «Завод застонал» (о заводе, где гудит гудок). 2. «Он съел тарелку» (о нейтральном столовом разговоре). 3. «Ну и погода!» (в солнечный день). 4. «Умный в гору не пойдёт». 5. «Рыжая осень». 6. «Белеет парус».',
  key:'1. Олицетворение (завод издаёт стоны). 2. Метонимия (тарелка вместо супа). 3. Ирония (хвалят плохую погоду) или прямая похвала — зависит от погоды: в солнечный день — прямая похвала, в дождливый — ирония. 4. Пословица (антитеза «умный — гору») — не троп. 5. Метафорический эпитет («рыжая осень»). 6. Инверсия (сказуемое впереди) и олицетворение.'},
 {n:90,l:7,st:4,task:'Спишите текст, вставляя пропущенные буквы и знаки препинания. Подчеркнуть и назвать три выразительных средства.',
  obr:'Тума_ (н) лёг на луг густым пологом: «густым пологом» — метафора.',
  body:'Тума_ лёг на луг, и всё замерло: и тр_ва, и дерев_я, и дальние холмы. Не слышно было ни шороха ни звука только где то далеко капл_ упала в воду. Казалось, что до станции целый день пути.',
  key:'Туман лёг на луг, и всё замерло: и трава, и деревья, и дальние холмы. Не слышно было ни шороха, ни звука, только где-то далеко капля упала в воду. Казалось, что до станции целый день пути. Средства: многосоюзие («и трава, и деревья, и холмы»), олицетворение («лёг на луг»), гипербола («целый день пути»), повтор «ни…ни». Орфография: туман, трава, деревья, капля; знаки: запятые при повторяющемся «ни»; «где-то» через дефис.'},
 {n:91,l:7,st:4,os:'диктант',task:'Выполнить предупредительный диктант. Перед записью выписать и объяснить слова с орфограммами, затем записать текст под диктовку, подчеркнуть эпитеты и сравнения.',
  body:'Подобно островам, разбросанным по бесконечно разлившейся реке, обтекающей их глубоко прозрачными рукавами ровной синевы, они почти не трогаются с места; далее, к небосклону, они сдвигаются, теснятся, синевы между ними уже не видать; но сами они так же лазурны, как небо: они все насквозь проникнуты светом и теплотой. (И. С. Тургенев, «Бежин луг») …на месте, где оно закатилось так же спокойно, как спокойно взошло на небо, алое сиянье стоит недолгое время над потемневшей землёй, и, тихо мигая, как бережно несомая свечка, затеплится на нём вечерняя звезда. (И. С. Тургенев, «Бежин луг»)',
  key:'Слова для проверки: разбросанным, бесконечно, разлившейся, обтекающей, прозрачными, рукавами, лазурны, проникнуты, теплотой, потемневшей, несомая, затеплится. Эпитеты: глубоко прозрачными, ровной (синевы), лазурны, алое (сиянье), вечерняя (звезда). Сравнения: «подобно островам», «так же лазурны, как небо», «как бережно несомая свечка». Проверять орфограммы в словах с удвоенными согласными, в причастиях и в приставках.'},
 {n:92,l:7,st:4,task:'Переложить художественное описание в научное: заменить образные слова точными терминами. Записать оба варианта и объяснить различие задач.',
  body:'Чуден Днепр при тихой погоде, когда вольно и плавно мчит сквозь леса и горы полные воды свои. (Н. В. Гоголь, «Страшная месть»)',
  key:'Научный вариант (образец): Днепр — крупная река Восточной Европы; в тихую погоду течение его спокойное и ровное. Образные слова «чуден» (оценка автора), «вольно и плавно мчит» (олицетворение и эпитеты) заменены нейтральными «спокойное, ровное течение». Различие: наука сообщает точные сведения, а художественный текст создаёт образ и выражает восхищение.'},
 {n:93,l:7,st:5,os:'сочинение',task:'Написать сочинение-рассуждение «Что делает речь выразительной» (10–12 предложений). Использовать примеры звукописи, тропов и фигур, показать их роль.',
  key:'Проверить: тезис; три-четыре примера разных уровней с названиями; к каждому указана роль; вывод. Образец: Выразительная речь не только говорит, но и показывает. Звукопись, как в строках Пушкина о шипении пены, даёт услышать. Тропы вроде олицетворения «поёт зима» оживляют картину. Анафора усиливает чувство. Поэтому выразительность — не украшение, а способ точнее передать мысль.'},
 {n:94,l:7,st:5,os:'анализ текста',task:'Проанализировать прозаический отрывок по плану урока (звуки, тропы, фигуры, роль, вывод), в 8–10 предложениях.',
  body:'С самого раннего утра небо ясно; утренняя заря не пылает пожаром: она разливается кротким румянцем. (И. С. Тургенев, «Бежин луг») К вечеру эти облака исчезают; последние из них, черноватые и неопределённые, как дым… (И. С. Тургенев, «Бежин луг»)',
  key:'Проверить: тема и настроение (мирное, ясное утро, постепенное угасание дня); звуки (мягкие [р], [з], [л] — плавность); тропы (метафора и антитеза пожара и румянца, олицетворение «заря разливается», сравнение «как дым», эпитеты «кротким», «черноватые»); фигуры (антитеза, длинные предложения с однородными членами); роль вместе (создаёт спокойное, кроткое настроение); вывод о способе Тургенева рисовать природу.'},
 {n:95,l:7,st:5,task:'Задание для абитуриентов. Прочитать текст. Указать номера верных утверждений.',
  body:'Текст: (1) Осенний лес стоял, как нарядный старик. (2) Осина перебирала листья, словно считала золото. (3) Дорога вела вдаль, и вдали — тишина, и ещё дальше — тишина. (4) Я шёл, и всё казалось мне чудесным.<br>Утверждения: 1) В предложении 1 есть сравнение. 2) В предложении 2 есть олицетворение и сравнение. 3) В предложении 3 есть многосоюзие. 4) В предложении 3 есть лексический повтор. 5) В предложении 4 есть эпитет «чудесным». 6) В тексте нет метафор.',
  key:'Верные утверждения: 1, 2, 3, 4. Пояснения: 5 — неверно: «чудесным» — обычное определение; 6 — неверно: «стоял, как нарядный старик» — сравнение, но «нарядный старик» — олицетворение; метафора в тексте всё же есть: слово «золото» (листья как золото) — перенос по сходству.'},
 {n:96,l:7,st:5,os:'исследование',task:'Выбрать два стихотворения разных авторов о природе. Составить таблицу: какие средства (звукопись, тропы, фигуры) в них есть и сколько. Сравнить настроение и сказать, какие средства его создают. Вывод — 4–5 предложений.',
  key:'Проверить: выбраны два стихотворения; таблица из трёх столбцов (звуки — тропы — фигуры) для обоих; средства названы верно; приведены слова-примеры; сравнение настроений опирается на таблицу; вывод. Пример вывода: В стихотворении А преобладают олицетворения и эпитеты — настроение живое, тёплое; в стихотворении Б — антитеза и риторические вопросы — настроение тревожное.'},
];
const VY_LNAMES=['',...VY.lessons.map(l=>l.t),'Повторение'];
const VY_BOOKREF={1:'Адамчик, «Самый полный курс русского языка», разделы «Выразительность речи», «Эхо» (звуковая выразительность); Розенталь, «Практический справочник», гл. 25 (стилистические фигуры)',2:'Розенталь, «Практический справочник», § 108–115 (метафора, метонимия, синекдоха, ирония, аллегория, олицетворение, перифраза), упр. 120–126; Розенталь, Голуб, Теленкова, «Современный русский язык», § 8',3:'Розенталь, «Практический справочник», § 106–107, 111 (эпитет, сравнение, гипербола, литота), упр. 119–123',4:'Розенталь, «Практический справочник», § 116–125 (анафора, эпифора, параллелизм, антитеза, градация, инверсия, эллипсис, умолчание, обращение, вопрос, многосоюзие, бессоюзие), упр. 127–132; Адамчик, раздел «Период»; Розенталь, «Справочник по пунктуации», раздел 13',5:'Розенталь, «Практический справочник», повторительные упражнения 133–134 (сопоставление фигур, тропы в отрывке)',6:'Розенталь, «Практический справочник», упр. 133–134; Адамчик, «Эхо» (разбор «Эха» Пушкина)',7:'Розенталь, «Практический справочник», гл. 24–25'};
